-- Extensions
create extension if not exists pg_trgm;
create extension if not exists "uuid-ossp";
create extension if not exists pgcrypto;
create extension if not exists pg_cron;

-- Tables (generated columns added later, after functions exist)
-- Extensions
create extension if not exists pg_trgm;
create extension if not exists "uuid-ossp";
create extension if not exists pgcrypto;
create extension if not exists pg_cron;

-- Tables
CREATE TABLE public."api_usage" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "at" timestamp with time zone DEFAULT now() NOT NULL,
  "email" text,
  "action" text NOT NULL,
  "ms" integer,
  "ok" boolean,
  "err" text,
  "ua" text,
  "ip" text,
  PRIMARY KEY (id)
);

CREATE TABLE public."app_props" (
  "key" text NOT NULL,
  "value" text DEFAULT ''::text,
  PRIMARY KEY (key)
);

CREATE TABLE public."attendance" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "rep" text NOT NULL,
  "rep_key" text NOT NULL,
  "day" date NOT NULL,
  "branch" text DEFAULT ''::text,
  "check_in_ts" timestamp with time zone,
  "check_in_lat" numeric,
  "check_in_lng" numeric,
  "check_in_distance_m" numeric,
  "check_in_photo" text,
  "check_out_ts" timestamp with time zone,
  "check_out_lat" numeric,
  "check_out_lng" numeric,
  "check_out_distance_m" numeric,
  "check_out_photo" text,
  "check_in_item" text,
  "check_out_item" text,
  "check_in_item_original" text,
  "check_out_item_original" text,
  PRIMARY KEY (id)
);

CREATE TABLE public."auth_fail" (
  "email" text NOT NULL,
  "n" integer DEFAULT 0 NOT NULL,
  "until" timestamp with time zone,
  PRIMARY KEY (email)
);

CREATE TABLE public."branches" (
  "name" text NOT NULL,
  "lat" numeric,
  "lng" numeric,
  "updated_at" timestamp with time zone DEFAULT now(),
  PRIMARY KEY (name)
);

CREATE TABLE public."eval_cache" (
  "mk" text NOT NULL,
  "at" timestamp with time zone NOT NULL,
  "data" jsonb NOT NULL,
  PRIMARY KEY (mk)
);

CREATE TABLE public."item_targets" (
  "id" bigint GENERATED ALWAYS AS IDENTITY NOT NULL,
  "rep" text DEFAULT ''::text NOT NULL,
  "rep_key" text DEFAULT ''::text NOT NULL,
  "code" text DEFAULT ''::text NOT NULL,
  "item_name" text DEFAULT ''::text NOT NULL,
  "month_key" text DEFAULT ''::text NOT NULL,
  "target" numeric,
  "bonus" numeric,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  "updated_at" timestamp with time zone DEFAULT now() NOT NULL,
  "extra_codes" text[] DEFAULT '{}'::text[] NOT NULL,
  "require_main_pct" numeric,
  PRIMARY KEY (id)
);

CREATE TABLE public."items" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
