-- Row Level Security (locked by default; all access goes through the SECURITY DEFINER api() function)
alter table public."api_usage" enable row level security;
alter table public."app_props" enable row level security;
alter table public."auth_fail" enable row level security;
alter table public."eval_cache" enable row level security;
alter table public."item_targets" enable row level security;
alter table public."items" enable row level security;
alter table public."jard" enable row level security;
alter table public."mirror_log" enable row level security;
alter table public."mirror_stage" enable row level security;
alter table public."prices" enable row level security;
alter table public."product_desc" enable row level security;
alter table public."reps" enable row level security;
alter table public."sales" enable row level security;
alter table public."sessions" enable row level security;
alter table public."stale_reasons" enable row level security;
alter table public."suggestions" enable row level security;
alter table public."targets" enable row level security;
alter table public."tawrid" enable row level security;
alter table public."write_requests" enable row level security;


-- Functions
CREATE OR REPLACE FUNCTION public.allowed_branches(p_admin text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  with rows as (
    select r.sheet_row, r.rep_key, r.branch_raw,
           array(select rkey(s) from unnest(split_sups(jtxt(r.raw -> 'المشرف المسؤول'))) s) sups
    from reps r
  ), used as (select * from rows where cardinality(sups) > 0)
  select case
    when not exists (select 1 from used) then null
    when exists (select 1 from used where rep_key = rkey(p_admin) and sups && array[rkey('الكل'), rkey('كل الفروع'), rkey('all')]) then null
    else coalesce((
      select jsonb_agg(b order by ord) from (
        select x.b, min(u.sheet_row::bigint * 1000 + x.o) ord
        from used u cross join lateral unnest(parse_branches(u.branch_raw)) with ordinality x(b, o)
        where rkey(p_admin) = any(u.sups)
        group by x.b
      ) z), '[]'::jsonb)
  end
$function$;

CREATE OR REPLACE FUNCTION public.api(p_action text, p_args jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare t0 timestamptz := clock_timestamp(); res jsonb; v_ok boolean; u2 jsonb;
begin
  if p_action = 'serverUsage' then
    res := (public.api_usage_report_(p_args) || jsonb_build_object('ms', (extract(epoch from clock_timestamp() - t0) * 1000)::int))::jsonb;
  elsif p_action = 'repsTargets' then
    res := (public.api_reps_targets_(p_args) || jsonb_build_object('ms', (extract(epoch from clock_timestamp() - t0) * 1000)::int))::jsonb;
  elsif p_action = 'itemBalancesBootstrap' then
    res := (public.item_balances_bootstrap_(p_args) || jsonb_build_object('ms', (extract(epoch from clock_timestamp() - t0) * 1000)::int))::jsonb;
  elsif p_action = 'itemBalancesReport' then
    res := (public.item_balances_report_(p_args) || jsonb_build_object('ms', (extract(epoch from clock_timestamp() - t0) * 1000)::int))::jsonb;
  elsif p_action = 'attendanceReport' then
    u2 := public.t_user(p_args -> 0);
    if u2 ? 'err' then res := jsonb_build_object('ok', false, 'error', u2 ->> 'err');
    else res := jsonb_build_object('ok', true, 'result', public.t_attendance_report(u2, coalesce(p_args ->> 1, ''), coalesce(p_args ->> 2, ''))); end if;
  elsif p_action = 'attendanceToday' then
    u2 := public.t_user(p_args -> 0);
    if u2 ? 'err' then res := jsonb_build_object('ok', false, 'error', u2 ->> 'err');
    else res := jsonb_build_object('ok', true, 'result', public.t_attendance_today(u2)); end if;
  elsif p_action = 'attendanceBranches' then
    u2 := public.t_user(p_args -> 0);
    if u2 ? 'err' then res := jsonb_build_object('ok', false, 'error', u2 ->> 'err');
    else res := jsonb_build_object('ok', true, 'result', public.t_attendance_branches(u2)); end if;
  elsif p_action = 'attendanceChallenge' then
    u2 := public.t_user(p_args -> 0);
    if u2 ? 'err' then res := jsonb_build_object('ok', false, 'error', u2 ->> 'err');
    else res := jsonb_build_object('ok', true, 'result', public.t_attendance_challenge(u2, nullif(p_args ->> 1, ''), coalesce((p_args ->> 2)::boolean, false))); end if;
  elsif p_action in ('listRepNames','savePrices','saveStaleReason','saveMyProfile','setMyPhoto','addSuggestion','addProductDescription',
                     'deleteProductDescription','setAdProduct','clearAd','addRep','setRepPin','setRepBranch','setRepFullName','setRepJobCode',
                     'setRepAdmin','setRepSupervisors','deleteRep','addAsnaf','setItemSeason','setBranchLocation','checkIn','checkOut',
                     'setAttendanceStartDate','setRepLeave','removeRepLeave','saveTarget') then
    res := public.api_settings_(p_action, p_args);
  else
    res := public.api_core(p_action, p_args);
  end if;
  v_ok := coalesce((to_jsonb(res) ->> 'ok')::boolean, true);
  perform public.api_usage_log_(p_action, to_jsonb(p_args), v_ok,
    case when not v_ok then to_jsonb(res) ->> 'error' end,
    (extract(epoch from clock_timestamp() - t0) * 1000)::int);
  return res;
end $function$;

CREATE OR REPLACE FUNCTION public.api_core(p_action text, p_args jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  t0 timestamptz := clock_timestamp(); u jsonb; a jsonb := coalesce(p_args, '[]'); res jsonb; v_n int;
begin
  if p_action not in ('bootstrapHome','bootstrapMyStats','bootstrapStale','listMyInvoices','getInvoiceDetails','getMyBalances',
     'bootstrapBalances','bootstrapItemSalesReport','bootstrapRepEvaluation','bootstrapProfile','listSuggestions','listProductDescriptions',
     'getStaleReasonsReport','bootstrapAdmin','listReps','listAsnaf','bootstrapPrices','bootstrapInvoice','bootstrapJard','bootstrapTawrid','getSaleStock',
     'finalizeInvoice','saveJard','saveTawrid') then
    return jsonb_build_object('ok', false, 'error', 'طلب غير معروف: ' || coalesce(p_action, ''));
  end if;

  u := t_user(a -> 0);
  if u ? 'err' then
    if coalesce((u ->> 'fail')::boolean, false) then
      insert into auth_fail as f (email, n) values (lower(norm(jtxt(a -> 0 -> 'email'))), 1)
        on conflict (email) do update set n = case when f.until is not null and f.until <= now() then 1 else f.n + 1 end,
                                          until = case when f.until is not null and f.until <= now() then null else f.until end
        returning n into v_n;
      if v_n >= 5 then update auth_fail set until = now() + interval '15 minutes', n = 0 where email = lower(norm(jtxt(a -> 0 -> 'email'))); end if;
    end if;
    return jsonb_build_object('ok', false, 'error', u ->> 'err');
  end if;
  delete from auth_fail where email = u ->> 'email' and until is null;

  begin
    res := case p_action
      when 'bootstrapHome' then jsonb_build_object('user', u, 'isAdmin', (u -> 'isAdmin'), 'targetProgress', t_target_progress(u), 'ad', t_ad(), 'stats', t_home_stats(u))
      when 'bootstrapMyStats' then t_my_stats(u, jtxt(a -> 1))
      when 'bootstrapStale' then t_bootstrap_stale(u, jtxt(a -> 1))
      when 'listMyInvoices' then t_list_invoices(u, a -> 1)
      when 'getInvoiceDetails' then t_invoice_details(u, jtxt(a -> 1))
      when 'getMyBalances' then (
        select case when not coalesce((u ->> 'isAdmin')::boolean, false) and jsonb_array_length(b) > 0
          then jsonb_build_object('user', u, 'isAdmin', false, 'blocked', true, 'blockItems', b, 'blockWindowDays', 30, 'balances', '[]'::jsonb)
          else jsonb_build_object('user', u, 'repName', u -> 'name', 'branch', u -> 'branch', 'balances', t_balances(u ->> 'name', u ->> 'branch')) end
        from (select case when coalesce((u ->> 'isAdmin')::boolean, false) then '[]'::jsonb else t_block_items(u) end b) x)
      when 'bootstrapBalances' then t_bootstrap_balances(u, jtxt(a -> 1), jtxt(a -> 2))
      when 'bootstrapItemSalesReport' then t_item_sales(u, jtxt(a -> 1), jtxt(a -> 2))
      when 'bootstrapRepEvaluation' then t_bootstrap_eval(u, jtxt(a -> 1))
      when 'bootstrapProfile' then t_profile(u)
      when 'listSuggestions' then t_list_suggestions(u)
      when 'listProductDescriptions' then t_list_products()
      when 'getStaleReasonsReport' then t_stale_reasons_report(u)
      when 'bootstrapAdmin' then (case when not is_owner(u) then t_list_reps(u) else
        jsonb_build_object('reps', t_list_reps(u), 'asnaf', t_list_asnaf(u), 'suggestions', t_list_suggestions(u),
                           'products', t_list_products(), 'activeAd', t_ad()) end)
      when 'listReps' then t_list_reps(u)
      when 'listAsnaf' then t_list_asnaf(u)
      when 'bootstrapPrices' then jsonb_build_object('user', u, 'asnaf', t_asnaf_raw(), 'prices', t_my_prices(u ->> 'email'))
      when 'bootstrapInvoice' then jsonb_build_object('user', u, 'asnaf', t_asnaf_raw(),
        'type', case when jtxt(a -> 1) = 'مرتجع' then 'مرتجع' else 'بيع' end, 'prices', t_my_prices(u ->> 'email'))
      when 'bootstrapJard' then t_bootstrap_jard(u)
      when 'bootstrapTawrid' then jsonb_build_object('user', u, 'asnaf', t_asnaf_raw())
      when 'getSaleStock' then t_sale_stock(u)
      when 'finalizeInvoice' then t_finalize(u, jtxt(a -> 1), a -> 2, jtxt(a -> 3), coalesce((a ->> 4)::boolean, false))
      when 'saveJard' then t_save_stock(u, 'jard', a -> 1, jtxt(a -> 2))
      when 'saveTawrid' then t_save_stock(u, 'tawrid', a -> 1, jtxt(a -> 2))
    end;
  exception when others then
    return jsonb_build_object('ok', false, 'error', sqlerrm);
  end;
  return jsonb_build_object('ok', true, 'result', res, 'ms', round(extract(epoch from clock_timestamp() - t0) * 1000), 'src', 'sb');
end $function$;

CREATE OR REPLACE FUNCTION public.api_item_targets_auth_(p_cred jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare chk jsonb; u jsonb;
begin
  chk := public.api_core('bootstrapHome', jsonb_build_array(p_cred));
  if coalesce((chk ->> 'ok')::boolean, false) is not true then
    return jsonb_build_object('err', coalesce(chk ->> 'error', 'تعذر التحقق'));
  end if;
  u := chk -> 'result' -> 'user';
  if not (coalesce((u ->> 'isAdmin')::boolean, false) or public.is_owner(u)) then
    return jsonb_build_object('err', 'غير مصرح لك بالصفحة دي');
  end if;
  return u;
end $function$;

CREATE OR REPLACE FUNCTION public.api_item_targets_bootstrap_(p_args jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  u jsonb := public.api_item_targets_auth_(p_args -> 0);
  v_mk text := norm(coalesce(p_args ->> 1, ''));
  v_months jsonb; v_reps jsonb; v_items jsonb; v_rows jsonb;
begin
  if u ? 'err' then return jsonb_build_object('ok', false, 'error', u ->> 'err'); end if;

  select jsonb_agg(to_char((date_trunc('month', biz_today()) - make_interval(months => g))::date, 'YYYY-MM') order by g)
    into v_months from generate_series(0, 11) g;
  if not v_months @> to_jsonb(v_mk) then v_mk := v_months ->> 0; end if;

  select coalesce(jsonb_agg(name order by name collate ar_sort), '[]')
    into v_reps from reps where name <> '' and not is_admin;

  select coalesce(jsonb_agg(jsonb_build_object('code', code, 'name', name) order by name collate ar_sort), '[]')
    into v_items from items where code <> '';

  select coalesce(jsonb_agg(jsonb_build_object(
      'rep', rep, 'code', code, 'itemName', item_name, 'target', target, 'bonus', bonus,
      'extraCodes', coalesce(extra_codes, '{}'), 'noTarget', (target is null), 'requireMainPct', require_main_pct
    ) order by rep collate ar_sort, item_name), '[]')
    into v_rows from item_targets where month_key = v_mk;

  return jsonb_build_object('ok', true, 'result', jsonb_build_object(
    'monthKey', v_mk, 'months', v_months, 'reps', v_reps, 'items', v_items, 'rows', v_rows
  ));
end $function$;

CREATE OR REPLACE FUNCTION public.api_item_targets_report_(p_args jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  u jsonb := public.api_item_targets_auth_(p_args -> 0);
  v_mk text := norm(coalesce(p_args ->> 1, ''));
  v_months jsonb; v_m0 date; v_m1 date;
  v_rows jsonb; v_total_bonus numeric;
begin
  if u ? 'err' then return jsonb_build_object('ok', false, 'error', u ->> 'err'); end if;

  select jsonb_agg(to_char((date_trunc('month', biz_today()) - make_interval(months => g))::date, 'YYYY-MM') order by g)
    into v_months from generate_series(0, 11) g;
  if not v_months @> to_jsonb(v_mk) then v_mk := v_months ->> 0; end if;
  v_m0 := to_date(v_mk || '-01', 'YYYY-MM-DD');
  v_m1 := (v_m0 + interval '1 month')::date;

  with t as (
    select *, array_cat(array[code], coalesce(extra_codes, '{}')) all_codes
    from item_targets where month_key = v_mk and coalesce(bonus, 0) > 0
  ), s as (
    select rep_key, code, sum(coalesce(qty, 0)) q
    from sales where day >= v_m0 and day < v_m1 and coalesce(code, '') <> ''
    group by rep_key, code
  ), rb as (
    select rep_key, array_to_string(parse_branches(branch_raw), '، ') br,
      nullif(raw ->> 'الاسم الكامل', '') full_name, nullif(raw ->> 'الكود الوظيفي', '') job_code
    from reps where rep_key <> ''
  ), maint as (
    select distinct on (rep_key) rep_key, target from targets
    where month_key = v_mk and coalesce(target, 0) > 0 and coalesce(rep, '') <> ''
    order by rep_key, sheet_row desc
  ), mains as (
    select rep_key,
      sum(case when coalesce(qty, 0) > 0 then coalesce(total, 0) else 0 end)
      - sum(case when coalesce(qty, 0) < 0 and coalesce(return_kind, '') <> 'رجوع للشركة' then abs(coalesce(total, 0)) else 0 end) net
    from sales where day >= v_m0 and day < v_m1 and coalesce(rep_key, '') <> '' group by rep_key
  ), mainpct as (
    select maint.rep_key, case when maint.target > 0 then r1(coalesce(mains.net, 0) / maint.target * 100) end pct
    from maint left join mains on mains.rep_key = maint.rep_key
  ), x as (
    select t.rep, coalesce(rb.br, '') branch, rb.full_name, rb.job_code, t.code, t.item_name, t.target, coalesce(t.bonus, 0) bonus_per_piece,
      t.require_main_pct, mp.pct main_pct,
      r2(coalesce((select sum(s.q) from s where s.rep_key = t.rep_key and s.code = any(t.all_codes)), 0)) achieved
    from t left join rb on rb.rep_key = t.rep_key left join mainpct mp on mp.rep_key = t.rep_key
  ), y as (
    select *, case when target > 0 then r1(achieved / target * 100) end pct,
      (target is null or achieved >= target) item_ok,
      (require_main_pct is null or coalesce(main_pct, 0) >= require_main_pct) main_ok
    from x
  ), z as (
    select *, (item_ok and main_ok) qualifies,
      case when item_ok and main_ok then r2(achieved * bonus_per_piece) else 0 end bonus_earned
    from y
  )
  select
    coalesce(jsonb_agg(jsonb_build_object(
      'rep', rep, 'fullName', full_name, 'jobCode', job_code, 'branch', branch, 'code', code, 'name', item_name, 'target', target, 'achieved', achieved,
      'pct', pct, 'bonus', bonus_per_piece, 'bonusEarned', bonus_earned,
      'requireMainPct', require_main_pct, 'mainPct', main_pct, 'mainOk', main_ok
    ) order by rep collate ar_sort, item_name), '[]'),
    coalesce(sum(bonus_earned), 0)
  into v_rows, v_total_bonus
  from z;

  return jsonb_build_object('ok', true, 'result', jsonb_build_object(
    'monthKey', v_mk, 'months', v_months, 'rows', v_rows, 'totalBonus', r2(v_total_bonus)
  ));
end $function$;

CREATE OR REPLACE FUNCTION public.api_item_targets_save_(p_args jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  u jsonb := public.api_item_targets_auth_(p_args -> 0);
  v_rep text := norm(p_args ->> 1);
  v_code text := norm(p_args ->> 2);
  v_mk text := norm(p_args ->> 3);
  v_target numeric := nullif(p_args ->> 4, '')::numeric;
  v_bonus numeric := nullif(p_args ->> 5, '')::numeric;
  v_extra text[];
  v_delete boolean := coalesce((p_args ->> 7)::boolean, false);
  v_require_main_pct numeric := nullif(p_args ->> 8, '')::numeric;
  v_item_name text;
  v_rk text;
begin
  if u ? 'err' then return jsonb_build_object('ok', false, 'error', u ->> 'err'); end if;
  if v_rep = '' or v_code = '' or v_mk !~ '^[0-9]{4}-[0-9]{2}$' then
    return jsonb_build_object('ok', false, 'error', 'بيانات ناقصة');
  end if;
  v_rk := rkey(v_rep);

  if v_delete then
    delete from item_targets where rep_key = v_rk and code = v_code and month_key = v_mk;
    return jsonb_build_object('ok', true, 'result', true);
  end if;

  if coalesce(v_bonus, 0) <= 0 then
    return jsonb_build_object('ok', false, 'error', 'اكتب قيمة البونص');
  end if;
  select name into v_item_name from items where code = v_code limit 1;
  select coalesce(array_agg(distinct trim(x)), '{}') into v_extra
    from jsonb_array_elements_text(coalesce(p_args -> 6, '[]'::jsonb)) x
    where trim(x) <> '' and trim(x) <> v_code;

  insert into item_targets (rep, rep_key, code, item_name, month_key, target, bonus, extra_codes, require_main_pct, updated_at)
  values (v_rep, v_rk, v_code, coalesce(v_item_name, ''), v_mk, v_target, v_bonus, v_extra, v_require_main_pct, now())
  on conflict (rep_key, code, month_key)
  do update set rep = excluded.rep, item_name = excluded.item_name,
    target = excluded.target, bonus = excluded.bonus, extra_codes = excluded.extra_codes,
    require_main_pct = excluded.require_main_pct, updated_at = now();
  return jsonb_build_object('ok', true, 'result', true);
end $function$;

CREATE OR REPLACE FUNCTION public.api_reps_targets_(p_args jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare chk jsonb; u jsonb;
begin
  chk := public.api_core('bootstrapHome', (jsonb_build_array(to_jsonb(p_args) -> 0))::jsonb);
  if coalesce((to_jsonb(chk) ->> 'ok')::boolean, false) is not true then return to_jsonb(chk); end if;
  u := to_jsonb(chk) -> 'result' -> 'user';
  if not (coalesce((u ->> 'isAdmin')::boolean, false) or public.is_owner(u)) then
    return jsonb_build_object('ok', false, 'error', 'غير مصرح لك بمشاهدة الصفحة دي');
  end if;
  return jsonb_build_object('ok', true, 'result', public.t_reps_targets(u, to_jsonb(p_args) ->> 1));
end $function$;

CREATE OR REPLACE FUNCTION public.api_settings_(p_action text, p_args jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare
  t0 timestamptz := clock_timestamp(); a jsonb := coalesce(p_args, '[]'); u jsonb; res jsonb; v_n int;
  v_email text; v_name text; v_pin text; v_code text; v_txt text; v_br text; v_mk text; v_num numeric; r record; v_arr text[]; x jsonb;
  v_lat numeric; v_lng numeric; v_photo text; v_item text; v_item_orig text; v_day date; v_rk text;
  v_season text; v_is_season_reason boolean; v_off_season boolean;
begin
  if p_action = 'listRepNames' then
    select coalesce(jsonb_agg(name order by name collate ar_sort), '[]') into res from (select distinct name from reps where name <> '') q;
    return jsonb_build_object('ok', true, 'result', res, 'src', 'sb');
  end if;

  u := t_user(a -> 0);
  if u ? 'err' then
    if coalesce((u ->> 'fail')::boolean, false) then
      insert into auth_fail as f (email, n) values (lower(norm(jtxt(a -> 0 -> 'email'))), 1)
        on conflict (email) do update set n = case when f.until is not null and f.until <= now() then 1 else f.n + 1 end,
                                          until = case when f.until is not null and f.until <= now() then null else f.until end
        returning n into v_n;
      if v_n >= 5 then update auth_fail set until = now() + interval '15 minutes', n = 0 where email = lower(norm(jtxt(a -> 0 -> 'email'))); end if;
    end if;
    return jsonb_build_object('ok', false, 'error', u ->> 'err');
  end if;

  begin
    case p_action

    when 'savePrices' then
      if jsonb_array_length(coalesce(a -> 1, '[]')) = 0 then raise exception 'مفيش أسعار مكتوبة للحفظ'; end if;
      delete from prices where email = u ->> 'email';
      v_n := t_next_row('prices') - 1;
      insert into prices (sheet_row, email, item_name, price, raw)
      select v_n + o, u ->> 'email', norm(e ->> 'itemName'), (e ->> 'price')::numeric,
             jsonb_build_object('الإيميل', u ->> 'email', 'اسم الصنف', norm(e ->> 'itemName'), 'السعر', (e ->> 'price')::numeric)
        from jsonb_array_elements(a -> 1) with ordinality x(e, o)
       where norm(e ->> 'itemName') <> '' and (e ->> 'price') ~ '^\s*[0-9]+(\.[0-9]+)?\s*$' and (e ->> 'price')::numeric >= 0;
      get diagnostics v_n = row_count;
      res := jsonb_build_object('ok', true, 'count', v_n);

    when 'saveStaleReason' then
      v_code := norm(jtxt(a -> 1)); v_txt := norm(jtxt(a -> 2));
      if v_code = '' then raise exception 'كود الصنف مفقود'; end if;
      if v_txt = '' then raise exception 'من فضلك اكتب السبب قبل الإرسال'; end if;
      select b into v_br from jsonb_array_elements_text(coalesce(u -> 'branches', '[]')) b where nar(b) = nar(jtxt(a -> 3)) limit 1;
      v_br := coalesce(v_br, u ->> 'branch', '');
      if v_code = any(resolved_codes(v_br)) then
        res := jsonb_build_object('ok', true, 'alreadyResolved', true);
      else
        if length(regexp_replace(v_txt, '[^؀-ۿA-Za-z0-9]', '', 'g')) < 6 then
          raise exception 'السبب ده قصير جدًا أو غير واضح — اكتب سبب حقيقي ومفهوم';
        end if;

        select coalesce(raw ->> 'الموسم', '') into v_season from items where norm(code) = v_code order by sheet_row limit 1;
        v_is_season_reason := (v_txt ilike '%سيزون%' or v_txt ilike '%موسم%');
        v_off_season := case coalesce(v_season, '')
          when 'شتوي' then extract(month from biz_today())::int not in (11, 12, 1, 2)
          when 'صيفي' then extract(month from biz_today())::int not in (5, 6, 7, 8, 9)
          else false
        end;

        if not (v_is_season_reason and v_season <> '' and v_off_season) then
          if exists (
            select 1 from stale_reasons sr
            where sr.rep_key = rkey(u ->> 'name') and similarity(sr.reason, v_txt) > 0.6
          ) then
            raise exception 'السبب ده قريب جدًا من سبب كتبته قبل كده لصنف تاني — اكتب سبب مختلف وحقيقي للصنف ده';
          end if;
        end if;

        select name into v_name from items where norm(code) = v_code order by sheet_row limit 1;
        insert into stale_reasons (sheet_row, code, item_name, branch, rep, rep_key, reason, day, raw)
        values (t_next_row('stale_reasons'), v_code, coalesce(v_name, ''), v_br, u ->> 'name', rkey(u ->> 'name'), v_txt, biz_today(),
                jsonb_build_object('كود الصنف', v_code, 'اسم الصنف', coalesce(v_name, ''), 'الفرع', v_br, 'المندوب', u ->> 'name',
                                   'السبب', v_txt, 'تاريخ الكتابة', t_ymd(biz_today())));
        res := jsonb_build_object('ok', true);
      end if;

    when 'saveMyProfile' then
      x := coalesce(a -> 1, '{}');
      if nullif(jtxt(x -> 'age'), '') is not null and (jtxt(x -> 'age') !~ '^[0-9]+$' or (x ->> 'age')::int not between 16 and 75) then raise exception 'اكتب سن صحيح'; end if;
      if nullif(jtxt(x -> 'experienceYears'), '') is not null and (jtxt(x -> 'experienceYears') !~ '^[0-9]+(\.[0-9]+)?$' or (x ->> 'experienceYears')::numeric not between 0 and 60) then raise exception 'اكتب عدد سنوات خبرة صحيح'; end if;
      update reps set raw = coalesce(raw, '{}') || jsonb_build_object(
          'السن', case when nullif(jtxt(x -> 'age'), '') is null then to_jsonb(''::text) else to_jsonb((x ->> 'age')::int) end,
          'سنوات الخبرة', case when nullif(jtxt(x -> 'experienceYears'), '') is null then to_jsonb(''::text) else to_jsonb((x ->> 'experienceYears')::numeric) end,
          'الإجازة الأسبوعية', (select coalesce(jsonb_agg(d), '[]') from jsonb_array_elements_text(coalesce(x -> 'weeklyOff', '[]')) d
                                where d in ('الأحد','الإثنين','الثلاثاء','الأربعاء','الخميس','الجمعة','السبت'))::text)
       where email = u ->> 'email';
      res := jsonb_build_object('ok', true);

    when 'setMyPhoto' then
      v_txt := norm(jtxt(a -> 1));
      if v_txt !~ '^https://llbvttieimysqxyrdwph\.supabase\.co/storage/v1/object/public/' then raise exception 'لينك الصورة مش سليم'; end if;
      update reps set raw = coalesce(raw, '{}') || jsonb_build_object('الصورة', v_txt) where email = u ->> 'email';
      res := jsonb_build_object('ok', true, 'url', v_txt);

    when 'addSuggestion' then
      v_txt := norm(jtxt(a -> 1));
      if v_txt = '' then raise exception 'اكتب المقترح الأول'; end if;
      if length(v_txt) > 2000 then raise exception 'المقترح طويل أوي، اختصره شوية'; end if;
      insert into suggestions (sheet_row, day, rep, email, body, raw)
      values (t_next_row('suggestions'), biz_today(), u ->> 'name', u ->> 'email', v_txt,
              jsonb_build_object('التاريخ', t_ymd(biz_today()), 'اسم المندوب', u ->> 'name', 'الإيميل', u ->> 'email', 'النص', v_txt));
      res := jsonb_build_object('ok', true);

    when 'addProductDescription' then
      if not is_owner(u) then raise exception 'غير مصرح لك بإضافة وصف منتجات'; end if;
      v_name := norm(jtxt(a -> 1));
      v_txt := (select coalesce(string_agg(norm(l), E'\n' order by o) filter (where norm(l) <> ''), '') from regexp_split_to_table(coalesce(jtxt(a -> 2), ''), '\r?\n') with ordinality t(l, o));
      if v_name = '' or v_txt = '' then raise exception 'اكتب اسم المنتج والمواصفات'; end if;
      if length(v_txt) > 5000 then raise exception 'المواصفات طويلة أوي، اختصرها شوية'; end if;
      x := coalesce(a -> 3, '[]');
      if jsonb_typeof(x) <> 'array' or jsonb_array_length(x) > 5 then raise exception 'أقصى عدد صور للمنتج الواحد هو 5 صور'; end if;
      v_code := coalesce(nullif(norm(jtxt(a -> 4)), ''), substr(md5(random()::text || clock_timestamp()::text), 1, 8));
      insert into product_desc (sheet_row, pid, name, specs, photos, added, raw)
      values (t_next_row('product_desc'), v_code, v_name, v_txt, x::text, t_ymd(biz_today()),
              jsonb_build_object('المعرف', v_code, 'اسم المنتج', v_name, 'المواصفات', v_txt, 'الصور', x::text, 'تاريخ الإضافة', t_ymd(biz_today())));
      res := jsonb_build_object('ok', true, 'photos', x);

    when 'deleteProductDescription' then
      if not is_owner(u) then raise exception 'غير مصرح لك بحذف وصف منتجات'; end if;
      v_code := norm(jtxt(a -> 1));
      delete from product_desc where norm(jtxt(raw -> 'المعرف')) = v_code or norm(pid) = v_code;
      if not found then raise exception 'المنتج ده مش موجود'; end if;
      if (t_ad() ->> 'productId') = v_code then delete from app_props where key = 'active_ad_v1'; end if;
      res := jsonb_build_object('ok', true);

    when 'setAdProduct' then
      if not is_owner(u) then raise exception 'غير مصرح لك بإدارة الإعلان'; end if;
      x := t_build_ad(jtxt(a -> 1));
      delete from app_props where key = 'active_ad_v1';
      insert into app_props (key, value) values ('active_ad_v1', x::text);
      res := jsonb_build_object('ok', true, 'ad', x);

    when 'clearAd' then
      if not is_owner(u) then raise exception 'غير مصرح لك بإدارة الإعلان'; end if;
      delete from app_props where key = 'active_ad_v1';
      res := jsonb_build_object('ok', true);

    when 'addRep' then
      if not is_owner(u) then raise exception 'غير مصرح لك بإضافة مناديب جدد'; end if;
      v_name := norm(jtxt(a -> 1)); v_email := lower(norm(jtxt(a -> 2))); v_pin := norm(jtxt(a -> 3));
      if v_name = '' or v_email !~ '^[^\s@]+@[^\s@]+\.[^\s@]+$' then raise exception 'من فضلك اكتب اسم وإيميل صحيحين'; end if;
      if v_pin !~ '^[0-9]{4,6}$' then raise exception 'كود الدخول (PIN) لازم يكون من 4 لـ 6 أرقام'; end if;
      if exists (select 1 from reps where lower(email) = v_email) then raise exception 'الإيميل ده مسجل بالفعل لمندوب تاني'; end if;
      if exists (select 1 from reps where nar(name) = nar(v_name)) then raise exception 'الاسم ده مسجل بالفعل لمندوب تاني — اختر اسم مختلف شوية عشان ميحصلش لبس وقت تسجيل الدخول'; end if;
      if exists (select 1 from reps where pin = v_pin) then raise exception 'كود الدخول ده مستخدم بالفعل مع مندوب تاني — اختر كود مختلف'; end if;
      v_br := norm(jtxt(a -> 4));
      insert into reps (sheet_row, name, rep_key, email, pin, branch_raw, is_admin, supervisor, raw)
      values (t_next_row('reps'), v_name, rkey(v_name), v_email, v_pin, v_br, false, '',
              jsonb_build_object('الاسم', v_name, 'الإيميل', v_email, 'PIN', v_pin, 'الفرع', v_br, 'مشرف', false));
      res := jsonb_build_object('ok', true, 'name', v_name, 'email', v_email);

    when 'setRepPin' then
      if not is_owner(u) then raise exception 'غير مصرح لك بتغيير أكواد الدخول'; end if;
      v_email := lower(norm(jtxt(a -> 1))); v_pin := norm(jtxt(a -> 2));
      if v_pin !~ '^[0-9]{4,6}$' then raise exception 'كود الدخول لازم يكون من 4 لـ 6 أرقام'; end if;
      if exists (select 1 from reps where pin = v_pin and lower(email) <> v_email) then raise exception 'كود الدخول ده مستخدم بالفعل مع مندوب تاني — اختر كود مختلف'; end if;
      update reps set pin = v_pin, raw = coalesce(raw, '{}') || jsonb_build_object('PIN', v_pin) where lower(email) = v_email;
      if not found then raise exception 'الإيميل ده مش موجود'; end if;
      res := jsonb_build_object('ok', true, 'email', v_email);

    when 'setRepBranch' then
      if not is_owner(u) then raise exception 'غير مصرح لك بتغيير الفروع'; end if;
      v_email := lower(norm(jtxt(a -> 1)));
      v_br := array_to_string(parse_branches(jtxt(a -> 2)), '، ');
      update reps set branch_raw = v_br, raw = coalesce(raw, '{}') || jsonb_build_object('الفرع', v_br) where lower(email) = v_email;
      if not found then raise exception 'الإيميل ده مش موجود'; end if;
      res := jsonb_build_object('ok', true, 'email', v_email, 'branch', v_br);

    when 'setRepFullName' then
      if not is_owner(u) then raise exception 'غير مصرح لك بتغيير بيانات المناديب'; end if;
      v_email := lower(norm(jtxt(a -> 1))); v_txt := norm(jtxt(a -> 2));
      update reps set raw = coalesce(raw, '{}') || jsonb_build_object('الاسم الكامل', v_txt) where lower(email) = v_email;
      if not found then raise exception 'الإيميل ده مش موجود'; end if;
      res := jsonb_build_object('ok', true, 'email', v_email, 'fullName', v_txt);

    when 'setRepJobCode' then
      if not is_owner(u) then raise exception 'غير مصرح لك بتغيير بيانات المناديب'; end if;
      v_email := lower(norm(jtxt(a -> 1))); v_txt := norm(jtxt(a -> 2));
      update reps set raw = coalesce(raw, '{}') || jsonb_build_object('الكود الوظيفي', v_txt) where lower(email) = v_email;
      if not found then raise exception 'الإيميل ده مش موجود'; end if;
      res := jsonb_build_object('ok', true, 'email', v_email, 'jobCode', v_txt);

    when 'setRepAdmin' then
      if not is_owner(u) then raise exception 'غير مصرح لك بتغيير صلاحيات الإشراف'; end if;
      v_email := lower(norm(jtxt(a -> 1)));
      if v_email = 'elzenoukisales@gmail.com' and not coalesce((a ->> 2)::boolean, false) then raise exception 'لا يمكن إلغاء صلاحية الإشراف عن هذا الحساب — محمي بشكل دائم'; end if;
      if not coalesce((a ->> 2)::boolean, false) and (select count(*) from reps where is_admin) <= 1 and exists (select 1 from reps where lower(email) = v_email and is_admin) then
        raise exception 'لا يمكن إلغاء آخر مشرف في النظام — لازم يفضل مشرف واحد على الأقل';
      end if;
      update reps set is_admin = coalesce((a ->> 2)::boolean, false), raw = coalesce(raw, '{}') || jsonb_build_object('مشرف', coalesce((a ->> 2)::boolean, false))
       where lower(email) = v_email;
      if not found then raise exception 'الإيميل ده مش موجود'; end if;
      res := jsonb_build_object('ok', true, 'email', v_email, 'isAdmin', coalesce((a ->> 2)::boolean, false));

    when 'setRepSupervisors' then
      if not is_owner(u) then raise exception 'غير مصرح لك بتغيير المشرفين'; end if;
      v_email := lower(norm(jtxt(a -> 1))); v_arr := '{}';
      for v_txt in select norm(s) from jsonb_array_elements_text(coalesce(a -> 2, '[]')) s where norm(s) <> '' loop
        if rkey(v_txt) in (rkey('الكل'), rkey('كل الفروع'), rkey('all')) then v_name := 'الكل';
        else select name into v_name from reps where is_admin and rkey(name) = rkey(v_txt) order by sheet_row limit 1;
          if v_name is null then raise exception '"%" مش مشرف — فعّله كمشرف الأول', v_txt; end if;
        end if;
        if not (v_name = any(v_arr)) then v_arr := v_arr || v_name; end if;
        v_name := null;
      end loop;
      update reps set supervisor = array_to_string(v_arr, '، '), raw = coalesce(raw, '{}') || jsonb_build_object('المشرف المسؤول', array_to_string(v_arr, '، '))
       where lower(email) = v_email;
      if not found then raise exception 'الإيميل ده مش موجود'; end if;
      res := jsonb_build_object('ok', true, 'email', v_email, 'supervisors', to_jsonb(v_arr));

    when 'deleteRep' then
      if not is_owner(u) then raise exception 'غير مصرح لك بحذف مناديب'; end if;
      v_email := lower(norm(jtxt(a -> 1)));
      if v_email = u ->> 'email' then raise exception 'لا يمكنك حذف نفسك من هنا'; end if;
      if v_email = 'elzenoukisales@gmail.com' then raise exception 'لا يمكن حذف هذا الحساب — محمي بشكل دائم'; end if;
      if exists (select 1 from reps where lower(email) = v_email and is_admin) and (select count(*) from reps where is_admin) <= 1 then
        raise exception 'لا يمكن حذف آخر مشرف في النظام — لازم يفضل مشرف واحد على الأقل';
      end if;
      delete from reps where lower(email) = v_email;
      if not found then raise exception 'الإيميل ده مش موجود'; end if;
      res := jsonb_build_object('ok', true, 'email', v_email);

    when 'addAsnaf' then
      if not coalesce((u ->> 'isAdmin')::boolean, false) then raise exception 'غير مصرح لك بإضافة أصناف جديدة'; end if;
      v_code := norm(jtxt(a -> 1)); v_name := norm(jtxt(a -> 2));
      if v_name = '' then raise exception 'من فضلك اكتب اسم الصنف'; end if;
      if v_code <> '' and exists (select 1 from items where norm(code) = v_code) then raise exception 'الكود ده مسجل بالفعل لصنف تاني'; end if;
      if exists (select 1 from items where norm(name) = v_name) then raise exception 'اسم الصنف ده موجود بالفعل'; end if;
      insert into items (sheet_row, code, name, raw) values (t_next_row('items'), v_code, v_name, jsonb_build_object('الكود', v_code, 'اسم الصنف', v_name));
      res := jsonb_build_object('ok', true, 'code', v_code, 'name', v_name);

    when 'setItemSeason' then
      if not coalesce((u ->> 'isAdmin')::boolean, false) then raise exception 'غير مصرح لك بتعديل الأصناف'; end if;
      v_code := norm(jtxt(a -> 1)); v_txt := norm(jtxt(a -> 2));
      if v_txt <> '' and v_txt not in ('شتوي', 'صيفي') then raise exception 'الموسم لازم يكون شتوي أو صيفي أو فاضي (دائم)'; end if;
      update items set raw = coalesce(raw, '{}') || jsonb_build_object('الموسم', v_txt) where norm(code) = v_code;
      if not found then raise exception 'الصنف ده مش موجود'; end if;
      res := jsonb_build_object('ok', true, 'code', v_code, 'season', v_txt);

    when 'setBranchLocation' then
      if not is_owner(u) then raise exception 'غير مصرح لك بتحديد مواقع الفروع'; end if;
      v_name := norm(jtxt(a -> 1)); v_lat := nullif(jtxt(a -> 2), '')::numeric; v_lng := nullif(jtxt(a -> 3), '')::numeric;
      if v_name = '' then raise exception 'اسم الفرع مفقود'; end if;
      if v_lat is null or v_lng is null then raise exception 'الإحداثيات مفقودة'; end if;
      insert into branches (name, lat, lng, updated_at) values (v_name, v_lat, v_lng, now())
      on conflict (name) do update set lat = excluded.lat, lng = excluded.lng, updated_at = now();
      res := jsonb_build_object('ok', true, 'name', v_name, 'lat', v_lat, 'lng', v_lng);

    when 'checkIn' then
      v_lat := nullif(jtxt(a -> 1), '')::numeric; v_lng := nullif(jtxt(a -> 2), '')::numeric; v_photo := jtxt(a -> 3);
      v_item := jtxt(a -> 4); v_item_orig := jtxt(a -> 5);
      if v_lat is null or v_lng is null then raise exception 'محتاجين موقعك عشان تسجل حضور'; end if;
      res := t_attendance_checkin(u, v_lat, v_lng, v_photo, v_item, v_item_orig);

    when 'checkOut' then
      v_lat := nullif(jtxt(a -> 1), '')::numeric; v_lng := nullif(jtxt(a -> 2), '')::numeric; v_photo := jtxt(a -> 3);
      v_item := jtxt(a -> 4); v_item_orig := jtxt(a -> 5);
      if v_lat is null or v_lng is null then raise exception 'محتاجين موقعك عشان تسجل انصراف'; end if;
      res := t_attendance_checkout(u, v_lat, v_lng, v_photo, v_item, v_item_orig);

    when 'setAttendanceStartDate' then
      if not is_owner(u) then raise exception 'غير مصرح لك بتعديل الإعدادات دي'; end if;
      v_txt := norm(jtxt(a -> 1));
      if v_txt !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then raise exception 'التاريخ مش مظبوط'; end if;
      insert into app_props (key, value) values ('attendance_start_date', v_txt)
      on conflict (key) do update set value = v_txt;
      res := jsonb_build_object('ok', true, 'startDate', v_txt);

    when 'setRepLeave' then
      if not coalesce((u ->> 'isAdmin')::boolean, false) then raise exception 'غير مصرح لك بتسجيل إجازات'; end if;
      v_name := norm(jtxt(a -> 1)); v_txt := norm(jtxt(a -> 2));
      if v_txt !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then raise exception 'التاريخ مش مظبوط'; end if;
      select coalesce(nullif(rep_key, ''), rkey(name)) into v_rk from reps where nar(name) = nar(v_name) order by sheet_row limit 1;
      if v_rk is null then raise exception 'المندوب ده مش موجود'; end if;
      insert into rep_leaves (rep_key, day, reason) values (v_rk, v_txt::date, coalesce(jtxt(a -> 3), ''))
      on conflict (rep_key, day) do update set reason = excluded.reason;
      res := jsonb_build_object('ok', true);

    when 'removeRepLeave' then
      if not coalesce((u ->> 'isAdmin')::boolean, false) then raise exception 'غير مصرح لك بتعديل الإجازات'; end if;
      v_name := norm(jtxt(a -> 1)); v_txt := norm(jtxt(a -> 2));
      select coalesce(nullif(rep_key, ''), rkey(name)) into v_rk from reps where nar(name) = nar(v_name) order by sheet_row limit 1;
      if v_rk is null then raise exception 'المندوب ده مش موجود'; end if;
      delete from rep_leaves where rep_key = v_rk and day = v_txt::date;
      res := jsonb_build_object('ok', true);

    when 'saveTarget' then
      if not is_owner(u) then raise exception 'غير مصرح لك بتعديل التارجت'; end if;
      v_name := norm(jtxt(a -> 1)); v_mk := norm(jtxt(a -> 2));
      if v_mk !~ '^[0-9]{4}-[0-9]{2}$' then raise exception 'الشهر مش مظبوط'; end if;
      select name, coalesce(nullif(rep_key, ''), rkey(name)) k into r from reps where nar(name) = nar(v_name) order by sheet_row limit 1;
      if not found then raise exception 'المندوب ده مش موجود'; end if;
      v_num := nullif(regexp_replace(coalesce(jtxt(a -> 3), ''), '[^0-9.]', '', 'g'), '')::numeric;
      delete from targets where month_key = v_mk and (rep_key = r.k or nar(rep) = nar(r.name));
      if coalesce(v_num, 0) > 0 then
        insert into targets (sheet_row, rep, rep_key, month_key, target, raw)
        values (t_next_row('targets'), r.name, r.k, v_mk, v_num, jsonb_build_object('المندوب', r.name, 'الشهر', v_mk, 'التارجت', v_num));
      end if;
      res := jsonb_build_object('ok', true, 'target', v_num);

    else
      return jsonb_build_object('ok', false, 'error', 'طلب غير معروف: ' || coalesce(p_action, ''));
    end case;
  exception when others then
    return jsonb_build_object('ok', false, 'error', sqlerrm);
  end;
  return jsonb_build_object('ok', true, 'result', res, 'ms', round(extract(epoch from clock_timestamp() - t0) * 1000), 'src', 'sb');
end
$function$;

CREATE OR REPLACE FUNCTION public.api_usage_data_(p_days integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_days int := case when p_days in (1, 7, 30) then p_days else 7 end;
  v_from timestamptz; res jsonb;
begin
  -- "النهارده" = من 12 بالليل بتوقيت القاهرة، غير كده آخر 7 أو 30 يوم
  v_from := case when v_days = 1 then (date_trunc('day', now() at time zone 'Africa/Cairo') at time zone 'Africa/Cairo')
                 else now() - make_interval(days => v_days) end;

  with u as (
    select * from api_usage where at >= v_from
  ), names as (
    select distinct on (k) k, nm from (
      select lower(coalesce(to_jsonb(r) ->> 'email', to_jsonb(r) -> 'raw' ->> 'الإيميل', '')) k, to_jsonb(r) ->> 'name' nm from reps r
    ) z where k <> '' order by k
  ), per as (
    select coalesce(email, '') email, count(*) n, coalesce(sum(ms), 0) tms, r0(avg(ms)::numeric) avgms,
           count(*) filter (where ok is false) errs, max(at) last_at,
           count(distinct ua) devices, count(distinct ip) ips, count(distinct (at at time zone 'Africa/Cairo')::date) days
    from u group by coalesce(email, '')
  ), top_act as (
    select email, jsonb_agg(jsonb_build_object('a', action, 'n', n, 'ms', tms) order by n desc) acts from (
      select coalesce(email, '') email, action, count(*) n, coalesce(sum(ms), 0) tms,
             row_number() over (partition by coalesce(email, '') order by count(*) desc) rn
      from u group by coalesce(email, ''), action
    ) x where rn <= 6 group by email
  ), tot as (
    select count(*) n, coalesce(sum(ms), 0) tms, count(*) filter (where ok is false) errs,
           count(distinct email) filter (where email is not null) users from u
  ), med as (
    select percentile_cont(0.5) within group (order by n) m from per where email <> ''
  )
  select jsonb_build_object(
    'days', v_days, 'from', v_from,
    'total', (select n from tot), 'serverMs', (select tms from tot), 'errors', (select errs from tot), 'users', (select users from tot),
    'medianRequests', (select r0(m::numeric) from med),
    'byUser', coalesce((select jsonb_agg(jsonb_build_object(
        'email', p.email, 'name', coalesce(nm.nm, ''), 'requests', p.n, 'serverMs', p.tms, 'avgMs', p.avgms,
        'errors', p.errs, 'lastAt', p.last_at, 'devices', p.devices, 'ips', p.ips, 'activeDays', p.days,
        'share', case when (select n from tot) > 0 then r1((p.n * 100.0 / (select n from tot))::numeric) else 0 end,
        'heavy', p.email <> '' and p.n > 3 * greatest((select m from med), 1),
        'actions', coalesce(t.acts, '[]'::jsonb)) order by p.n desc)
      from per p left join names nm on nm.k = p.email left join top_act t on t.email = p.email), '[]'::jsonb),
    'byAction', coalesce((select jsonb_agg(jsonb_build_object('a', action, 'n', n, 'ms', tms, 'avgMs', avgms) order by n desc) from (
        select action, count(*) n, coalesce(sum(ms), 0) tms, r0(avg(ms)::numeric) avgms from u group by action order by count(*) desc limit 20) a), '[]'::jsonb),
    'byHour', (select jsonb_agg(coalesce(c, 0) order by h) from generate_series(0, 23) h
        left join (select extract(hour from at at time zone 'Africa/Cairo')::int hh, count(*) c from u group by 1) x on x.hh = h)
  ) into res;
  return res;
end $function$;

CREATE OR REPLACE FUNCTION public.api_usage_log_(p_action text, p_args jsonb, p_ok boolean, p_err text, p_ms integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare h jsonb; v_email text;
begin
  begin
    v_email := lower(nullif(btrim(coalesce(p_args -> 0 ->> 'email', '')), ''));
    -- طلبات الدخول: الإيميل في الخانة الأولى كنص (زي verifyLoginOtp)
    if v_email is null and jsonb_typeof(p_args -> 0) = 'string' and (p_args ->> 0) like '%@%' then
      v_email := lower(btrim(p_args ->> 0));
    end if;
  exception when others then v_email := null; end;
  begin h := nullif(current_setting('request.headers', true), '')::jsonb; exception when others then h := null; end;
  insert into api_usage (email, action, ms, ok, err, ua, ip)
  values (left(v_email, 120), left(coalesce(p_action, '?'), 60), p_ms, p_ok, left(p_err, 200),
          left(h ->> 'user-agent', 300),
          left(btrim(split_part(coalesce(h ->> 'x-forwarded-for', h ->> 'cf-connecting-ip', h ->> 'x-real-ip', ''), ',', 1)), 60));
  -- تنضيف تلقائي: بيشيل اللي أقدم من 90 يوم من وقت للتاني
  if random() < 0.002 then delete from api_usage where at < now() - interval '90 days'; end if;
exception when others then null;
end $function$;

CREATE OR REPLACE FUNCTION public.api_usage_report_(p_args jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare chk jsonb; v_days int;
begin
  chk := public.api_core('bootstrapHome', (jsonb_build_array(to_jsonb(p_args) -> 0))::jsonb);
  if coalesce((to_jsonb(chk) ->> 'ok')::boolean, false) is not true then return to_jsonb(chk); end if;
  if not public.is_owner(to_jsonb(chk) -> 'result' -> 'user') then
    return jsonb_build_object('ok', false, 'error', 'غير مصرح لك بمشاهدة الصفحة دي');
  end if;
  begin v_days := nullif(to_jsonb(p_args) ->> 1, '')::int; exception when others then v_days := 7; end;
  return jsonb_build_object('ok', true, 'result', public.api_usage_data_(coalesce(v_days, 7)));
end $function$;

