CREATE OR REPLACE FUNCTION public.branch_allowed(p_branch text, p_allowed jsonb)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select case when p_allowed is null or jsonb_typeof(p_allowed) = 'null' then true
    else exists (select 1 from jsonb_array_elements_text(p_allowed) a where nar(a) = nar(p_branch)) end
$function$;

CREATE OR REPLACE FUNCTION public.branches_allowed(p_cell text, p_allowed jsonb)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select case when p_allowed is null or jsonb_typeof(p_allowed) = 'null' then true
    else exists (select 1 from unnest(parse_branches(p_cell)) b, jsonb_array_elements_text(p_allowed) a where nar(a) = nar(b)) end
$function$;

