CREATE OR REPLACE FUNCTION public.ev2_cfg()
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select jsonb_build_object(
    'w_perf', 35, 'w_target', 15, 'w_sell', 20, 'w_stale', 15, 'w_ret', 10, 'w_commit', 5,
    'perf_full', 1.10,        -- 110% من المتوقع في فرعك = درجة أداء الفرع كاملة
    'base_months', 3,         -- تاريخ الفرع = آخر 3 شهور قبل الشهر
    'base_min_days', 10,      -- الفرع لازم يكون ليه 10 أيام بيع على الأقل في التاريخ ده
    'sell_full', 1.20,        -- تصريف 120% من متوسط المناديب = كاملة
    'stale_zero', 0.30,       -- 30% رواكد من أصنافك = صفر
    'ret_zero', 0.10,         -- مرتجع سليم 10% من البيع = صفر
    'ret_min_gross', 50000,   -- البيع أقل من كده: المرتجع مش بيتحسب
    'min_days', 15,           -- أقل من 15 يوم بيع (أو نص أيام شغل الشركة) = غير مكتمل
    'w3', jsonb_build_array(0.5, 0.3, 0.2)  -- أوزان الترتيب: الشهر الحالي، اللي قبله، اللي قبله
  )
$function$;

