CREATE OR REPLACE FUNCTION public.item_balances_auth_(p_cred jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare chk jsonb; u jsonb;
begin
  chk := public.api_core('bootstrapHome', jsonb_build_array(p_cred));
  if coalesce((chk ->> 'ok')::boolean, false) is not true then
    return jsonb_build_object('err', coalesce(chk ->> 'error', 'تعذر التحقق'));
  end if;
  u := chk -> 'result' -> 'user';
  if not (coalesce((u ->> 'isAdmin')::boolean, false) or public.is_owner(u)) then
    return jsonb_build_object('err', 'غير مصرح لك بالصفحة دي');
  end if;
  return u;
end $function$;

CREATE OR REPLACE FUNCTION public.item_balances_bootstrap_(p_args jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  u jsonb := public.item_balances_auth_(p_args -> 0);
  v_items jsonb;
begin
  if u ? 'err' then return jsonb_build_object('ok', false, 'error', u ->> 'err'); end if;
  select coalesce(jsonb_agg(jsonb_build_object('code', code, 'name', name) order by name collate ar_sort), '[]')
    into v_items from items where code <> '';
  return jsonb_build_object('ok', true, 'result', jsonb_build_object('items', v_items));
end $function$;

CREATE OR REPLACE FUNCTION public.item_balances_report_(p_args jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  u jsonb := public.item_balances_auth_(p_args -> 0);
  v_code text := norm(p_args ->> 1);
  v_name text;
  r record; b text; bal jsonb; v_bal numeric; v_has boolean;
  res jsonb := '[]'::jsonb; v_total numeric := 0;
begin
  if u ? 'err' then return jsonb_build_object('ok', false, 'error', u ->> 'err'); end if;
  if v_code = '' then return jsonb_build_object('ok', false, 'error', 'اختار الصنف الأول'); end if;
  select name into v_name from items where code = v_code limit 1;

  for r in
    select name, rep_key, parse_branches(branch_raw) br
    from reps where name <> '' and not is_admin order by name collate ar_sort
  loop
    foreach b in array (case when cardinality(r.br) = 0 then array[''] else r.br end) loop
      begin bal := t_balances(r.name, b); exception when others then bal := '[]'; end;
      select (e ->> 'balance')::numeric, (e ->> 'hasBaseline')::boolean into v_bal, v_has
        from jsonb_array_elements(bal) e where e ->> 'code' = v_code limit 1;
      if v_bal is not null and v_bal <> 0 then
        res := res || jsonb_build_object('rep', r.name, 'branch', b, 'balance', v_bal, 'hasBaseline', coalesce(v_has, false));
        v_total := v_total + v_bal;
      end if;
      v_bal := null; v_has := null;
    end loop;
  end loop;

  return jsonb_build_object('ok', true, 'result', jsonb_build_object(
    'itemCode', v_code, 'itemName', coalesce(v_name, v_code),
    'rows', (select coalesce(jsonb_agg(e order by (e ->> 'balance')::numeric desc), '[]') from jsonb_array_elements(res) e),
    'total', r2(v_total)
  ));
end $function$;

CREATE OR REPLACE FUNCTION public.js_number(v jsonb)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare s text;
begin
  if v is null or jsonb_typeof(v) = 'null' then return 0; end if;
  if jsonb_typeof(v) = 'number' then return (v #>> '{}')::numeric; end if;
  if jsonb_typeof(v) = 'boolean' then return case when (v #>> '{}')::boolean then 1 else 0 end; end if;
  if jsonb_typeof(v) <> 'string' then return null; end if;
  s := regexp_replace(v #>> '{}', '^[ \t\n\r\v\f   -   　﻿]+|[ \t\n\r\v\f   -   　﻿]+$', '', 'g');
  if s = '' then return 0; end if;
  if s ~ '^[+-]?([0-9]+\.?[0-9]*|\.[0-9]+)([eE][+-]?[0-9]+)?$' then return s::numeric; end if;
  return null;
end $function$;

CREATE OR REPLACE FUNCTION public.jtxt(v jsonb)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
AS $function$
  select case when v is null or jsonb_typeof(v) = 'null' then '' when jsonb_typeof(v) = 'string' then v #>> '{}' else v::text end
$function$;

