end $function$;

CREATE OR REPLACE FUNCTION public.mirror_stage_add(p_tab text, p_rows jsonb, p_reset boolean)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if mirror_table(p_tab) is null then raise exception 'تاب غير معروف: %', p_tab; end if;
  if p_reset then delete from mirror_stage where tab = p_tab; end if;
  insert into mirror_stage (tab, rows) values (p_tab, coalesce(p_rows, '[]'::jsonb));
  return jsonb_array_length(coalesce(p_rows, '[]'::jsonb));
end $function$;

CREATE OR REPLACE FUNCTION public.mirror_stage_commit(p_tab text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  raise exception 'المزامنة من الشيت متوقفة — الإعدادات بقت على Supabase';
end $function$;

CREATE OR REPLACE FUNCTION public.mirror_stats()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select jsonb_build_object(
    'sales',    (select jsonb_build_object('n', count(*), 'qty', coalesce(sum(qty), 0), 'total', coalesce(round(sum(total), 2), 0)) from sales where src is distinct from 'sb' or synced_at is not null),
    'sessions', (select jsonb_build_object('n', count(*)) from sessions where src is distinct from 'sb' or synced_at is not null),
    'jard',     (select jsonb_build_object('n', count(*), 'qty', coalesce(sum(count), 0)) from jard where src is distinct from 'sb' or synced_at is not null),
    'tawrid',   (select jsonb_build_object('n', count(*), 'qty', coalesce(sum(qty), 0)) from tawrid where src is distinct from 'sb' or synced_at is not null),
    'reps', (select count(*) from reps), 'items', (select count(*) from items), 'prices', (select count(*) from prices),
    'targets', (select count(*) from targets), 'suggestions', (select count(*) from suggestions),
    'product_desc', (select count(*) from product_desc), 'stale_reasons', (select count(*) from stale_reasons),
    'pending', (select count(*) from sales where src = 'sb' and synced_at is null),
    'lastSync', (select max(at) from mirror_log where kind = 'sync'))
$function$;

CREATE OR REPLACE FUNCTION public.mirror_sync(p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  insert into mirror_log (kind, detail) values ('blocked', jsonb_build_object('note', 'mirror_sync رفضت — Supabase هو الأصل'));
  return jsonb_build_object('blocked', true);
end $function$;

CREATE OR REPLACE FUNCTION public.mirror_table(p_tab text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select case p_tab
    when 'sales' then 'sales' when 'sessions' then 'sessions' when 'jard' then 'jard' when 'tawrid' then 'tawrid'
    when 'reps' then 'reps' when 'items' then 'items' when 'prices' then 'prices' when 'targets' then 'targets'
    when 'suggestions' then 'suggestions' when 'product_desc' then 'product_desc' when 'stale_reasons' then 'stale_reasons'
    when 'props' then 'app_props'
  end
$function$;

CREATE OR REPLACE FUNCTION public.nar(t text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
AS $function$
  select translate(norm(t), 'أإآةى', 'اااهي')
$function$;

CREATE OR REPLACE FUNCTION public.norm(t text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
AS $function$
  select case when t is null then '' else
    regexp_replace(
      regexp_replace(
        regexp_replace(t, '[​-‏‪-‮⁠-⁩؜﻿­]', '', 'g'),
        '^[ \t\n\r\v\f   -   　]+|[ \t\n\r\v\f   -   　]+$', '', 'g'),
      '[ \t\n\r\v\f   -   　]+', ' ', 'g')
  end
$function$;

CREATE OR REPLACE FUNCTION public.norm_lines(v text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select coalesce(string_agg(n, E'\n' order by o) filter (where n <> ''), '')
  from (select norm(l) n, o from regexp_split_to_table(coalesce(v, ''), E'\r?\n') with ordinality t(l, o)) a
$function$;

CREATE OR REPLACE FUNCTION public.outbox_mark(p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n1 int; n2 int; n3 int; n4 int;
begin
  update sales set synced_at = now() where src = 'sb' and synced_at is null and id in (select (jsonb_array_elements_text(coalesce(p -> 'sales', '[]')))::bigint);
  get diagnostics n1 = row_count;
  update sessions set synced_at = now() where src = 'sb' and synced_at is null and id in (select (jsonb_array_elements_text(coalesce(p -> 'sessions', '[]')))::bigint);
  get diagnostics n2 = row_count;
  update jard set synced_at = now() where src = 'sb' and synced_at is null and id in (select (jsonb_array_elements_text(coalesce(p -> 'jard', '[]')))::bigint);
  get diagnostics n3 = row_count;
  update tawrid set synced_at = now() where src = 'sb' and synced_at is null and id in (select (jsonb_array_elements_text(coalesce(p -> 'tawrid', '[]')))::bigint);
  get diagnostics n4 = row_count;
  insert into mirror_log (kind, detail) values ('outbox', jsonb_build_object('sales', n1, 'sessions', n2, 'jard', n3, 'tawrid', n4));
  return jsonb_build_object('sales', n1, 'sessions', n2, 'jard', n3, 'tawrid', n4);
end $function$;

CREATE OR REPLACE FUNCTION public.outbox_pending()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select jsonb_build_object(
    'sales', coalesce((select jsonb_agg(to_jsonb(s) - 'branch_key' - 'multi' order by id) from sales s where src = 'sb' and synced_at is null), '[]'),
    'sessions', coalesce((select jsonb_agg(to_jsonb(s) order by id) from sessions s where src = 'sb' and synced_at is null), '[]'),
    'jard', coalesce((select jsonb_agg(to_jsonb(s) - 'branch_key' order by id) from jard s where src = 'sb' and synced_at is null), '[]'),
    'tawrid', coalesce((select jsonb_agg(to_jsonb(s) - 'branch_key' order by id) from tawrid s where src = 'sb' and synced_at is null), '[]'))
$function$;

CREATE OR REPLACE FUNCTION public.parse_branches(v text)
 RETURNS text[]
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
AS $function$
  select coalesce(array_agg(x order by o), '{}') from (
    select distinct on (n) n x, o from (
      select norm(s) n, o from regexp_split_to_table(coalesce(v, ''), '[،,؛;|/]+') with ordinality t(s, o)
    ) a where n <> '' order by n, o
  ) b
$function$;

CREATE OR REPLACE FUNCTION public.pick_target(u jsonb, p_req text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare
  v_name text := u ->> 'name'; v_allowed jsonb := u -> 'allowedBranches';
  v_reps jsonb; v_target text := v_name; v_req text := norm(p_req); m record;
begin
  if not coalesce((u ->> 'isAdmin')::boolean, false) then
    return jsonb_build_object('target', v_name, 'reps', '[]'::jsonb);
  end if;
  -- المشرفين (is_admin) مش بيظهروا في القايمة دي — القايمة للمناديب (البروموترز) بس، لحد ما تتعمل خاصية تارجت مجمّع للمشرف
  select coalesce(jsonb_agg(name order by name collate ar_sort, sheet_row), '[]') into v_reps
    from reps where name <> '' and name <> v_name and not is_admin and branches_allowed(branch_raw, v_allowed);
  if v_req <> '' then
    select name, branch_raw into m from reps where name <> '' and not is_admin and nar(name) = nar(v_req) order by sheet_row limit 1;
    if found and (m.name = v_name or branches_allowed(m.branch_raw, v_allowed)) then v_target := m.name; end if;
  elsif jsonb_array_length(v_reps) > 0 then
    v_target := v_reps ->> 0;
  end if;
  return jsonb_build_object('target', v_target, 'reps', v_reps);
end $function$;

CREATE OR REPLACE FUNCTION public.psd(v jsonb)
 RETURNS date
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare s text; m text[]; d int; mo int; y int;
begin
  if v is null or jsonb_typeof(v) = 'null' then return null; end if;
  if jsonb_typeof(v) = 'number' then
    if (v #>> '{}')::numeric > 20000 and (v #>> '{}')::numeric < 80000 then
      return date '1899-12-30' + floor((v #>> '{}')::numeric)::int;
    end if;
  end if;
  s := translate(norm(jtxt(v)), '٠١٢٣٤٥٦٧٨٩۰۱۲۳۴۵۶۷۸۹', '01234567890123456789');
  if s = '' then return null; end if;
  m := regexp_match(s, '^([0-9]{1,2})[/.-]([0-9]{1,2})[/.-]([0-9]{4})([ T].*)?$');
  if m is not null then d := m[1]::int; mo := m[2]::int; y := m[3]::int;
  else
    m := regexp_match(s, '^([0-9]{4})[/.-]([0-9]{1,2})[/.-]([0-9]{1,2})([ T].*)?$');
    if m is null then return null; end if;
    y := m[1]::int; mo := m[2]::int; d := m[3]::int;
  end if;
  if mo > 12 or d > 31 or d = 0 or mo = 0 or y = 0 then return null; end if;
  return make_date(y, mo, 1) + (d - 1);
end $function$;

