CREATE OR REPLACE FUNCTION public.t_attendance_challenge(u jsonb, p_exclude text DEFAULT NULL::text, p_random boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare
  v_branch text := coalesce(u ->> 'branch', ''); bal jsonb; v_candidates jsonb; v_n int; v_idx int; v_seed text;
begin
  begin
    bal := t_balances(u ->> 'name', v_branch);
  exception when others then
    return jsonb_build_object('item', null);
  end;
  select coalesce(jsonb_agg(e order by e ->> 'name'), '[]') into v_candidates
    from jsonb_array_elements(bal) e
    where (e ->> 'balance')::numeric > 0 and (p_exclude is null or nar(e ->> 'name') <> nar(p_exclude));
  v_n := jsonb_array_length(v_candidates);
  if v_n = 0 then
    -- مفيش بديل غير المطلوب أصلاً (مثلاً صنف واحد بس في الرصيد) — ارجع نفسه تاني بدل ما ترجع فاضي
    if p_exclude is not null then
      select coalesce(jsonb_agg(e order by e ->> 'name'), '[]') into v_candidates
        from jsonb_array_elements(bal) e where (e ->> 'balance')::numeric > 0;
      v_n := jsonb_array_length(v_candidates);
    end if;
    if v_n = 0 then return jsonb_build_object('item', null); end if;
  end if;
  if p_random then
    -- طلب استبدال صريح من المندوب نفسه (ضغط "مش عندي الصنف ده"): اختيار عشوائي حقيقي
    v_idx := floor(random() * v_n)::int;
  else
    -- اختيار تلقائي ثابت طول اليوم لنفس المرحلة (حضور/انصراف) من غير ما نحتاج نخزن حاجة قبلها —
    -- بنفرّق الـseed لو ده صنف الانصراف (p_exclude = صنف الحضور) عشان يطلع مختلف عن صنف الحضور
    v_seed := rkey(u ->> 'name') || '|' || to_char(biz_today(), 'YYYY-MM-DD') || (case when p_exclude is not null then '|out' else '|in' end);
    v_idx := abs(('x' || substr(md5(v_seed), 1, 8))::bit(32)::int) % v_n;
  end if;
  return jsonb_build_object('item', (v_candidates -> v_idx) ->> 'name', 'code', (v_candidates -> v_idx) ->> 'code');
end
$function$;

CREATE OR REPLACE FUNCTION public.t_attendance_checkin(u jsonb, p_lat numeric, p_lng numeric, p_photo text, p_item text DEFAULT NULL::text, p_item_original text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare
  v_day date := biz_today(); v_rk text := rkey(u ->> 'name'); v_branch text := coalesce(u ->> 'branch', '');
  v_existing record; v_bloc record; v_dist numeric;
begin
  if v_rk = '' then raise exception 'مش معروف مين انت'; end if;
  select * into v_existing from attendance where rep_key = v_rk and day = v_day;
  if found and v_existing.check_in_ts is not null then
    raise exception 'سجّلت حضور النهارده بالفعل الساعة %', t_time12(v_existing.check_in_ts);
  end if;
  select lat, lng into v_bloc from branches where nar(name) = nar(v_branch);
  if v_bloc.lat is not null then
    v_dist := t_haversine_m(p_lat, p_lng, v_bloc.lat, v_bloc.lng);
  end if;
  insert into attendance (rep, rep_key, day, branch, check_in_ts, check_in_lat, check_in_lng, check_in_distance_m, check_in_photo, check_in_item, check_in_item_original)
  values (u ->> 'name', v_rk, v_day, v_branch, now(), p_lat, p_lng, v_dist, p_photo, nullif(p_item, ''),
          case when nullif(p_item_original, '') is not null and nullif(p_item_original, '') <> nullif(p_item, '') then p_item_original else null end)
  on conflict (rep_key, day) do update set
    branch = excluded.branch, check_in_ts = excluded.check_in_ts, check_in_lat = excluded.check_in_lat,
    check_in_lng = excluded.check_in_lng, check_in_distance_m = excluded.check_in_distance_m, check_in_photo = excluded.check_in_photo,
    check_in_item = excluded.check_in_item, check_in_item_original = excluded.check_in_item_original
  where attendance.check_in_ts is null;
  return jsonb_build_object('ok', true, 'branch', v_branch, 'distance', v_dist, 'time', t_time12(now()));
end
$function$;

CREATE OR REPLACE FUNCTION public.t_attendance_checkout(u jsonb, p_lat numeric, p_lng numeric, p_photo text, p_item text DEFAULT NULL::text, p_item_original text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare
  v_day date := biz_today(); v_rk text := rkey(u ->> 'name'); v_row record; v_bloc record; v_dist numeric;
begin
  if v_rk = '' then raise exception 'مش معروف مين انت'; end if;
  select * into v_row from attendance where rep_key = v_rk and day = v_day;
  if not found or v_row.check_in_ts is null then
    raise exception 'لازم تسجل حضور الأول قبل الانصراف';
  end if;
  if v_row.check_out_ts is not null then
    raise exception 'سجّلت انصراف بالفعل الساعة %', t_time12(v_row.check_out_ts);
  end if;
  select lat, lng into v_bloc from branches where nar(name) = nar(v_row.branch);
  if v_bloc.lat is not null then
    v_dist := t_haversine_m(p_lat, p_lng, v_bloc.lat, v_bloc.lng);
  end if;
  update attendance set check_out_ts = now(), check_out_lat = p_lat, check_out_lng = p_lng,
    check_out_distance_m = v_dist, check_out_photo = p_photo, check_out_item = nullif(p_item, ''),
    check_out_item_original = case when nullif(p_item_original, '') is not null and nullif(p_item_original, '') <> nullif(p_item, '') then p_item_original else null end
   where rep_key = v_rk and day = v_day;
  return jsonb_build_object('ok', true, 'distance', v_dist, 'time', t_time12(now()));
end
$function$;

CREATE OR REPLACE FUNCTION public.t_attendance_report(u jsonb, p_target text, p_month text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare
  v_all boolean := coalesce((u ->> 'isAdmin')::boolean, false) and norm(p_target) = '__ALL__';
  v_pick jsonb := pick_target(u, case when v_all then '' else p_target end);
  v_name text; v_rk text; v_mk text := norm(p_month);
  v_m0 date; v_m1 date; v_end date; v_today date := biz_today(); v_m0_eff date; v_start date := t_attendance_start_date();
  v_rows jsonb; v_expected int; v_present int; v_daysoff int; v_daysleave int; v_worked_min numeric; v_allowed jsonb := u -> 'allowedBranches';
  v_months jsonb;
begin
  if v_mk !~ '^[0-9]{4}-[0-9]{2}$' then v_mk := t_month_key(v_today); end if;
  v_m0 := make_date(split_part(v_mk, '-', 1)::int, split_part(v_mk, '-', 2)::int, 1);
  v_m1 := (v_m0 + interval '1 month')::date;
  v_end := least(v_m1 - 1, v_today);
  v_m0_eff := greatest(v_m0, v_start);

  select coalesce(jsonb_agg(to_char((date_trunc('month', v_today) - make_interval(months => g))::date, 'YYYY-MM') order by g), '[]')
    into v_months from generate_series(0, 5) g;

  if v_all then
    if v_m0_eff > v_end then
      return jsonb_build_object('user', u, 'isAdmin', true, 'allMode', true, 'repName', '__ALL__', 'reps', v_pick -> 'reps',
        'monthKey', v_mk, 'months', v_months, 'summaryRows', '[]'::jsonb, 'startDate', to_char(v_start, 'YYYY-MM-DD'));
    end if;
    with days as (
      select d::date d, (array['الأحد','الإثنين','الثلاثاء','الأربعاء','الخميس','الجمعة','السبت'])[extract(dow from d)::int + 1] dname
      from generate_series(v_m0_eff, v_end, interval '1 day') g(d)
    ), r as (
      select name, coalesce(nullif(rep_key, ''), rkey(name)) rk, raw ->> 'الإجازة الأسبوعية' off_raw
      from reps where name <> '' and not is_admin and branches_allowed(branch_raw, v_allowed)
    ), exp as (
      select r.name, r.rk,
        (select count(*) from days d where not (d.dname = any(t_weekly_off(coalesce(r.off_raw, ''))))
           and not exists (select 1 from rep_leaves lv where lv.rep_key = r.rk and lv.day = d.d)) expdays
      from r
    ), att as (
      select rep_key as rk, count(distinct day) filter (where check_in_ts is not null) present, max(check_in_ts) last_in
      from attendance where day >= v_m0_eff and day <= v_end group by rep_key
    )
    select coalesce(jsonb_agg(jsonb_build_object(
      'name', exp.name, 'expectedDays', exp.expdays, 'presentDays', coalesce(att.present, 0),
      'absentDays', greatest(exp.expdays - coalesce(att.present, 0), 0),
      'lastCheckIn', case when att.last_in is null then null else t_time12(att.last_in) end) order by exp.name collate ar_sort), '[]')
      into v_rows from exp left join att on att.rk = exp.rk;
    return jsonb_build_object('user', u, 'isAdmin', true, 'allMode', true, 'repName', '__ALL__', 'reps', v_pick -> 'reps',
      'monthKey', v_mk, 'months', v_months, 'summaryRows', v_rows, 'startDate', to_char(v_start, 'YYYY-MM-DD'));
  end if;

  v_name := v_pick ->> 'target'; v_rk := rkey(v_name);

  if v_m0_eff > v_end then
    return jsonb_build_object('user', u, 'isAdmin', coalesce((u ->> 'isAdmin')::boolean, false), 'allMode', false,
      'repName', v_name, 'reps', v_pick -> 'reps', 'monthKey', v_mk, 'months', v_months,
      'expectedDays', 0, 'presentDays', 0, 'daysOff', 0, 'daysLeave', 0, 'workedMinutes', 0, 'rows', '[]'::jsonb,
      'startDate', to_char(v_start, 'YYYY-MM-DD'));
  end if;

  with days as (
    select d::date d, (array['الأحد','الإثنين','الثلاثاء','الأربعاء','الخميس','الجمعة','السبت'])[extract(dow from d)::int + 1] dname
    from generate_series(v_m0_eff, v_end, interval '1 day') g(d)
  ), off as (
    select coalesce(raw ->> 'الإجازة الأسبوعية', '') o from reps where coalesce(nullif(rep_key, ''), rkey(name)) = v_rk order by sheet_row limit 1
  ), leaves as (
    select day from rep_leaves where rep_key = v_rk and day >= v_m0_eff and day <= v_end
  ), att as (
    select * from attendance where rep_key = v_rk and day >= v_m0_eff and day <= v_end
  ), cal as (
    select d.d, d.dname,
      case when lv.day is not null then 'leave'
           when d.dname = any(t_weekly_off(off.o)) then 'off'
           else 'workday' end dtype,
      a.*
    from days d cross join off
    left join leaves lv on lv.day = d.d
    left join att a on a.day = d.d
  )
  select
    coalesce(jsonb_agg(jsonb_build_object(
      'day', to_char(d, 'YYYY-MM-DD'), 'dayType', dtype, 'branch', branch,
      'checkIn', t_time12(check_in_ts), 'checkInDistance', check_in_distance_m, 'checkInItem', check_in_item, 'checkInItemOriginal', check_in_item_original, 'checkInPhoto', check_in_photo,
      'checkOut', t_time12(check_out_ts), 'checkOutDistance', check_out_distance_m, 'checkOutItem', check_out_item, 'checkOutItemOriginal', check_out_item_original, 'checkOutPhoto', check_out_photo,
      'durationMin', case when check_in_ts is not null and check_out_ts is not null then round(extract(epoch from (check_out_ts - check_in_ts)) / 60) end,
      'present', check_in_ts is not null
    ) order by d desc), '[]'),
    count(*) filter (where dtype = 'workday'),
    count(*) filter (where dtype = 'workday' and check_in_ts is not null),
    count(*) filter (where dtype = 'off'),
    count(*) filter (where dtype = 'leave'),
    coalesce(sum(extract(epoch from (check_out_ts - check_in_ts)) / 60) filter (where check_in_ts is not null and check_out_ts is not null), 0)
    into v_rows, v_expected, v_present, v_daysoff, v_daysleave, v_worked_min
  from cal;

  return jsonb_build_object('user', u, 'isAdmin', coalesce((u ->> 'isAdmin')::boolean, false), 'allMode', false,
    'repName', v_name, 'reps', v_pick -> 'reps', 'monthKey', v_mk, 'months', v_months,
    'expectedDays', v_expected, 'presentDays', v_present, 'daysOff', v_daysoff, 'daysLeave', v_daysleave,
    'workedMinutes', round(v_worked_min), 'rows', v_rows, 'startDate', to_char(v_start, 'YYYY-MM-DD'));
end
$function$;

CREATE OR REPLACE FUNCTION public.t_attendance_start_date()
 RETURNS date
 LANGUAGE sql
AS $function$
  select coalesce((select value::date from app_props where key = 'attendance_start_date'), '2000-01-01'::date)
$function$;

CREATE OR REPLACE FUNCTION public.t_attendance_today(u jsonb)
 RETURNS jsonb
 LANGUAGE sql
AS $function$
  select coalesce((
    select jsonb_build_object(
      'checkIn', t_time12(check_in_ts),
      'checkInDistance', check_in_distance_m,
      'checkInItem', check_in_item,
      'checkOut', t_time12(check_out_ts),
      'checkOutDistance', check_out_distance_m,
      'branch', branch
    )
    from attendance where rep_key = rkey(u ->> 'name') and day = biz_today()
  ), '{}'::jsonb)
$function$;

CREATE OR REPLACE FUNCTION public.t_balances(p_rep text, p_branch text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare
  v_name text := norm(p_rep); v_rk text := rkey(p_rep);
  v_rb text[] := rep_branches(p_rep); v_multi boolean; v_target text := ''; v_cur text; v_cut date; res jsonb; v_known text[];
begin
  v_multi := cardinality(v_rb) > 1;
  if v_multi then
    select b into v_target from unnest(v_rb) with ordinality x(b, o) where nar(b) = nar(p_branch) order by o limit 1;
    v_target := coalesce(v_target, v_rb[1]);
  end if;
  v_cur := coalesce(v_rb[1], '');

  v_known := array(select distinct nar(b) from reps, unnest(parse_branches(branch_raw)) b);

  if not v_multi and v_cur <> '' then
    select max(day) into v_cut from (
      select day from jard where rep_key = v_rk and branch <> '' and rkey(branch) <> rkey(v_cur) and nar(branch) = any(v_known)
      union all select day from tawrid where rep_key = v_rk and branch <> '' and rkey(branch) <> rkey(v_cur) and nar(branch) = any(v_known)
      union all select day from sales where rep_key = v_rk and branch <> '' and rkey(branch) <> rkey(v_cur) and nar(branch) = any(v_known)
    ) x;
  end if;

  with rows as (
    select 1 src, sheet_row, code, item_name, day, count qty, ts, branch, ''::text rkind from jard where rep_key = v_rk
    union all select 2, sheet_row, code, item_name, day, coalesce(qty, 0), ts, branch, '' from tawrid where rep_key = v_rk
    union all select 3, sheet_row, code, item_name, day, coalesce(qty, 0), ts, branch, return_kind from sales where rep_key = v_rk
  ), inb as (
    select * from rows r where
      case when v_multi then rkey(coalesce(nullif(r.branch, ''), v_rb[1])) = rkey(v_target)
      else not (r.branch <> '' and v_cur <> '' and rkey(r.branch) <> rkey(v_cur) and nar(r.branch) = any(v_known))
           and not (v_cut is not null and r.day is not null and (r.day < v_cut or (r.day = v_cut and r.branch = '')))
      end
  ), ok as (
    select * from inb where code <> '' and day is not null and (src <> 1 or qty is not null)
  ), ent as (
    select * from ok where not (src = 3 and qty < 0 and rkind = 'تالف')
  ), latest as (
    select distinct on (code) code, item_name from ok where item_name <> '' order by code, day desc, src, sheet_row
  ), asn as (
    select distinct on (code) code, name, coalesce(raw ->> 'الموسم', '') as season from items where code <> '' and name <> '' order by code, sheet_row desc
  ), codes as (
    select code from items where code <> '' union select code from ent
  ), bl as (
    select distinct on (code) code, qty bqty, day bday, ts bts from ent where src = 1
    order by code, day desc, coalesce(ts, 'epoch'::timestamptz) desc, sheet_row desc
  ), aft as (
    select e.code, sum(e.qty) filter (where e.src = 2) sq, sum(e.qty) filter (where e.src = 3) nq
    from ent e left join bl on bl.code = e.code
    where e.src in (2, 3) and (bl.bday is null or
      case when e.ts is not null and bl.bts is not null and e.day = bl.bday then e.ts > bl.bts else e.day >= bl.bday end)
    group by e.code
  ), bal as (
    select c.code, bl.code is not null has_b,
      r2(coalesce(bl.bqty, 0) + coalesce(aft.sq, 0) - coalesce(aft.nq, 0)) balance,
      coalesce(l.item_name, a.name, c.code) dname,
      coalesce(a.season, '') as season
    from codes c left join bl on bl.code = c.code left join aft on aft.code = c.code
    left join latest l on l.code = c.code left join asn a on a.code = c.code
  )
  select coalesce(jsonb_agg(jsonb_build_object('code', code, 'name', dname, 'balance', balance, 'hasBaseline', has_b, 'season', season)
         order by dname collate ar_sort, code), '[]') into res from bal;
  return res;
end
$function$;

CREATE OR REPLACE FUNCTION public.t_balances_asof(p_rep text, p_branch text, p_asof date)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare
  v_name text := norm(p_rep); v_rk text := rkey(p_rep);
  v_rb text[] := rep_branches(p_rep); v_multi boolean; v_target text := ''; v_cur text; v_cut date; res jsonb; v_known text[];
begin
  v_multi := cardinality(v_rb) > 1;
  if v_multi then
    select b into v_target from unnest(v_rb) with ordinality x(b, o) where nar(b) = nar(p_branch) order by o limit 1;
    v_target := coalesce(v_target, v_rb[1]);
  end if;
  v_cur := coalesce(v_rb[1], '');
  v_known := array(select distinct nar(b) from reps, unnest(parse_branches(branch_raw)) b);

  if not v_multi and v_cur <> '' then
    select max(day) into v_cut from (
      select day from jard where rep_key = v_rk and day <= p_asof and branch <> '' and rkey(branch) <> rkey(v_cur) and nar(branch) = any(v_known)
      union all select day from tawrid where rep_key = v_rk and day <= p_asof and branch <> '' and rkey(branch) <> rkey(v_cur) and nar(branch) = any(v_known)
      union all select day from sales where rep_key = v_rk and day <= p_asof and branch <> '' and rkey(branch) <> rkey(v_cur) and nar(branch) = any(v_known)
    ) x;
  end if;

  with rows as (
    select 1 src, sheet_row, code, item_name, day, count qty, ts, branch, ''::text rkind from jard where rep_key = v_rk and day <= p_asof
    union all select 2, sheet_row, code, item_name, day, coalesce(qty, 0), ts, branch, '' from tawrid where rep_key = v_rk and day <= p_asof
    union all select 3, sheet_row, code, item_name, day, coalesce(qty, 0), ts, branch, return_kind from sales where rep_key = v_rk and day <= p_asof
  ), inb as (
    select * from rows r where
      case when v_multi then rkey(coalesce(nullif(r.branch, ''), v_rb[1])) = rkey(v_target)
      else not (r.branch <> '' and v_cur <> '' and rkey(r.branch) <> rkey(v_cur) and nar(r.branch) = any(v_known))
           and not (v_cut is not null and r.day is not null and (r.day < v_cut or (r.day = v_cut and r.branch = '')))
      end
  ), ok as (
    select * from inb where code <> '' and day is not null and (src <> 1 or qty is not null)
  ), ent as (
    select * from ok where not (src = 3 and qty < 0 and rkind = 'تالف')
  ), bl as (
    select distinct on (code) code, qty bqty, day bday, ts bts from ent where src = 1
    order by code, day desc, coalesce(ts, 'epoch'::timestamptz) desc, sheet_row desc
  ), aft as (
    select e.code, sum(e.qty) filter (where e.src = 2) sq, sum(e.qty) filter (where e.src = 3) nq
    from ent e left join bl on bl.code = e.code
    where e.src in (2, 3) and (bl.bday is null or
      case when e.ts is not null and bl.bts is not null and e.day = bl.bday then e.ts > bl.bts else e.day >= bl.bday end)
    group by e.code
  ), codes as (
    select distinct code from ent
  )
  select coalesce(jsonb_agg(jsonb_build_object('code', c.code,
           'balance', r2(coalesce(bl.bqty, 0) + coalesce(aft.sq, 0) - coalesce(aft.nq, 0)))), '[]')
    into res
  from codes c left join bl on bl.code = c.code left join aft on aft.code = c.code;
  return res;
end $function$;

CREATE OR REPLACE FUNCTION public.t_block_items(u jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare v_br text[] := user_branches(u); b text; res jsonb := '[]'; lst jsonb; rc text[];
begin
  if cardinality(v_br) = 0 then
    if coalesce(u ->> 'branch', '') <> '' then v_br := array[u ->> 'branch']; else return '[]'; end if;
  end if;
  foreach b in array v_br loop
    lst := t_stale(b, 30, 200, u ->> 'name');
    if jsonb_array_length(lst) = 0 then continue; end if;
    rc := resolved_codes(b);
    select res || coalesce(jsonb_agg(jsonb_build_object('branch', b) || e order by o), '[]') into res
      from jsonb_array_elements(lst) with ordinality x(e, o) where not (norm(e ->> 'code') = any(rc));
  end loop;
  return res;
exception when others then return '[]';
end $function$;

CREATE OR REPLACE FUNCTION public.t_bootstrap_balances(u jsonb, p_target text, p_branch text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare v_blk jsonb; v_pick jsonb; v_name text; v_rb text[]; v_want text; v_shown text;
begin
  if not coalesce((u ->> 'isAdmin')::boolean, false) then
    v_blk := t_block_items(u);
    if jsonb_array_length(v_blk) > 0 then
      return jsonb_build_object('user', u, 'isAdmin', false, 'blocked', true, 'blockItems', v_blk, 'blockWindowDays', 30);
    end if;
  end if;
  v_pick := pick_target(u, p_target); v_name := v_pick ->> 'target';
  v_rb := rep_branches(v_name);
  v_want := norm(p_branch);
  if v_want = '' then v_want := case when v_name = u ->> 'name' then u ->> 'branch' else '' end; end if;
  select b into v_shown from unnest(v_rb) with ordinality x(b, o) where nar(b) = nar(v_want) order by o limit 1;
  v_shown := coalesce(v_shown, v_rb[1], '');
  return jsonb_build_object('user', u, 'repName', v_name, 'reps', v_pick -> 'reps',
    'repBranches', case when cardinality(v_rb) > 1 then to_jsonb(v_rb) else '[]'::jsonb end,
    'branch', v_shown, 'balances', t_balances(v_name, v_shown));
end $function$;

CREATE OR REPLACE FUNCTION public.t_bootstrap_eval(u jsonb, p_month text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare v_today date := biz_today(); v_months jsonb; v_raw text := coalesce(p_month, ''); v_v2 boolean; v_mk text; d jsonb; v_list jsonb; v_blk jsonb;
begin
  if not coalesce((u ->> 'isAdmin')::boolean, false) then
    v_blk := t_block_items(u);
    if jsonb_array_length(v_blk) > 0 then
      return jsonb_build_object('user', u, 'isAdmin', false, 'blocked', true, 'blockItems', v_blk, 'blockWindowDays', 30);
    end if;
  end if;

  v_v2 := left(v_raw, 3) = 'v2:';
  v_mk := norm(case when v_v2 then substr(v_raw, 4) else v_raw end);
  select jsonb_agg(to_char((date_trunc('month', v_today) - make_interval(months => g))::date, 'YYYY-MM') order by g) into v_months
    from generate_series(0, 5) g;
  if not v_months @> to_jsonb(v_mk) then v_mk := v_months ->> 0; end if;
  d := case when v_v2 then t_rep_evaluations_v2(v_mk) else t_rep_evaluations_cached(v_mk) end;
  if coalesce((u ->> 'isAdmin')::boolean, false) then
    select coalesce(jsonb_agg(e order by o), '[]') into v_list from jsonb_array_elements(d -> 'rows') with ordinality x(e, o)
      where branches_allowed(array_to_string(array(select jsonb_array_elements_text(e -> 'branches')), '،'), u -> 'allowedBranches');
  else
    select coalesce(jsonb_agg(e order by o), '[]') into v_list from jsonb_array_elements(d -> 'rows') with ordinality x(e, o)
      where rkey(e ->> 'name') = rkey(u ->> 'name');
  end if;
  return jsonb_build_object('user', u, 'isAdmin', coalesce((u ->> 'isAdmin')::boolean, false), 'monthKey', v_mk, 'months', v_months,
    'avgNet', d -> 'avgNet', 'total', d -> 'total', 'list', v_list,
    'v2', v_v2, 'season', d -> 'season', 'workDays', d -> 'workDays', 'weeks', d -> 'weeks',
    'minDays', d -> 'minDays', 'stMedian', d -> 'stMedian');
end
$function$;

CREATE OR REPLACE FUNCTION public.t_bootstrap_jard(u jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare v_bal jsonb := t_balances(u ->> 'name', u ->> 'branch'); v_hide boolean; res jsonb;
begin
  v_hide := not coalesce((u ->> 'isAdmin')::boolean, false) and jsonb_array_length(t_block_items(u)) > 0;
  select coalesce(jsonb_agg(
      a || case when v_hide then jsonb_build_object('expectedBalance', null, 'hasStock', coalesce((b ->> 'balance')::numeric > 0, false))
                else jsonb_build_object('expectedBalance', b -> 'balance') end order by o), '[]')
    into res
    from jsonb_array_elements(t_asnaf_raw()) with ordinality x(a, o)
    left join lateral (select e b from jsonb_array_elements(v_bal) e where norm(e ->> 'code') = norm(jtxt(a -> 'code')) limit 1) bb on true;
  return jsonb_build_object('user', u, 'asnaf', res, 'balancesHidden', v_hide);
end $function$;

CREATE OR REPLACE FUNCTION public.t_bootstrap_stale(u jsonb, p_branch text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare
  v_admin boolean := coalesce((u ->> 'isAdmin')::boolean, false); v_req text := norm(p_branch);
  v_ub text[] := user_branches(u); v_br text[] := '{}'; v_target text := u ->> 'branch'; v_items jsonb; v_pref text[]; v_own text; v_order text[]; b text; lst jsonb;
begin
  if v_admin then
    v_br := t_list_branches(u -> 'allowedBranches');
    foreach b in array v_ub loop if not (b = any(v_br)) then v_br := v_br || b; end if; end loop;
    select coalesce(array_agg(x order by x collate ar_sort, x), '{}') into v_br from unnest(v_br) x;
  elsif cardinality(v_ub) > 1 then
    v_br := v_ub;
  end if;

  if v_admin then
    v_target := '';
    if v_req <> '' then
      select x into v_target from unnest(v_br) with ordinality t(x, o) where nar(x) = nar(v_req) order by o limit 1;
      v_target := coalesce(v_target, '');
    end if;
    if v_target = '' then
      if u -> 'allowedBranches' is null or jsonb_typeof(u -> 'allowedBranches') = 'null' then v_pref := v_br;
      else select coalesce(array_agg(x order by o), '{}') into v_pref from unnest(v_br) with ordinality t(x, o) where branch_allowed(x, u -> 'allowedBranches');
      end if;
      select x into v_own from unnest(v_pref) with ordinality t(x, o) where nar(x) = nar(u ->> 'branch') order by o limit 1;
      if v_own is not null then v_order := array[v_own] || array(select x from unnest(v_pref) with ordinality t(x, o) where x <> v_own order by o);
      else v_order := v_pref; end if;
      foreach b in array v_order loop
        begin lst := t_stale(b, 21, 60, ''); exception when others then lst := '[]'; end;
        if jsonb_array_length(lst) > 0 then v_target := b; v_items := lst; exit; end if;
      end loop;
      if v_target = '' then v_target := coalesce(v_order[1], u ->> 'branch'); end if;
    end if;
  elsif v_req <> '' then
    select x into v_own from unnest(v_ub) with ordinality t(x, o) where nar(x) = nar(v_req) order by o limit 1;
    if v_own is not null then v_target := v_own; end if;
  end if;
  if v_items is null then
    begin v_items := t_stale(v_target, 21, 60, case when v_admin then '' else u ->> 'name' end);
    exception when others then v_items := '[]'; end;
  end if;
  return jsonb_build_object('user', u, 'branch', v_target, 'branches', to_jsonb(v_br), 'windowDays', 21, 'items', v_items);
end $function$;

CREATE OR REPLACE FUNCTION public.t_build_ad(p_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare p record; v_specs text; v_lines text[]; l text; v_tag text := ''; v_out jsonb := '[]'; v_photos jsonb; parts text[];
begin
  select norm(jtxt(raw -> 'اسم المنتج')) nm, coalesce(jtxt(raw -> 'المواصفات'), '') sp,
         coalesce((select case when jsonb_typeof(j) = 'array' then j end from (select safe_jsonb(coalesce(nullif(norm(jtxt(raw -> 'الصور')), ''), '[]')) j) q), '[]') ph
    into p from product_desc where norm(jtxt(raw -> 'المعرف')) = norm(p_id) limit 1;
  if not found then raise exception 'المنتج ده مش موجود'; end if;
  select coalesce(array_agg(norm(x) order by o) filter (where norm(x) <> ''), '{}') into v_lines
    from regexp_split_to_table(p.sp, '\r?\n') with ordinality t(x, o);
  if cardinality(v_lines) < 2 and position('|' in array_to_string(v_lines, '')) = 0 then
    select coalesce(array_agg(norm(x) order by o) filter (where norm(x) <> ''), '{}') into v_lines
      from regexp_split_to_table(p.sp, '[•،]|\s-\s') with ordinality t(x, o);
  end if;
  foreach l in array v_lines loop
    if l ~ '^[*★]' then
      if v_tag = '' then v_tag := left(norm(regexp_replace(l, '^[*★]+', '')), 60); end if;
      continue;
    end if;
    parts := string_to_array(l, '|');
    if cardinality(parts) > 1 then
      v_out := v_out || jsonb_build_array(jsonb_build_object('v', left(norm(parts[1]), 20), 't', left(norm(array_to_string(parts[2:], ' ')), 40)));
    else
      v_out := v_out || jsonb_build_array(jsonb_build_object('v', '', 't', left(l, 60)));
    end if;
  end loop;
  select coalesce(jsonb_agg(e order by o), '[]') into v_photos from jsonb_array_elements(p.ph) with ordinality x(e, o) where o <= 3;
  select coalesce(jsonb_agg(e order by o), '[]') into v_out from jsonb_array_elements(v_out) with ordinality x(e, o) where o <= 5;
  return jsonb_build_object('id', substr(md5(random()::text || clock_timestamp()::text), 1, 8), 'productId', norm(p_id), 'name', left(p.nm, 60),
    'tagline', v_tag, 'specs', v_out, 'photos', v_photos, 'at', (extract(epoch from clock_timestamp()) * 1000)::bigint);
end $function$;

CREATE OR REPLACE FUNCTION public.t_code_for(p_name text)
 RETURNS TABLE(code_raw text, code text)
 LANGUAGE sql
 STABLE
AS $function$
  select code_raw, code from (
    select 1 o, * from t_item_by_name(p_name)
    union all
    select 2, '', code from (select code from items where code <> '' and rkey(name) = rkey(p_name) and rkey(p_name) <> '' order by sheet_row limit 1) z
    union all select 3, '', ''
  ) x order by o limit 1
$function$;

CREATE OR REPLACE FUNCTION public.t_finalize(u jsonb, p_type text, p_items jsonb, p_req text, p_confirm boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare
  v_ret boolean := p_type = 'مرتجع'; v_t text; v_key text; v_prev jsonb; v_today date := biz_today(); v_rk text := rkey(u ->> 'name');
  v_bal jsonb; v_short text[] := '{}'; r record; v_av numeric; v_sid text; v_dup jsonb; v_items jsonb := '[]'; v_total numeric := 0;
  it jsonb; v_name text; v_q numeric; v_p numeric; v_code record; v_signed numeric; v_line numeric; v_kind text; v_reason text; v_res jsonb; v_now timestamptz := now();
  v_req_sorted jsonb; v_match text; n int := 0; v_co boolean; v_nsales int := 0; v_nco int := 0; v_sales_items jsonb;
begin
  v_t := case when v_ret then 'مرتجع' else 'بيع' end;
  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'مفيش أصناف مضافة، ضيف صنف واحد على الأقل الأول';
  end if;
  perform pg_advisory_xact_lock(hashtext('fin:' || v_rk));
  v_key := case when norm(p_req) <> '' then 'finalizeInv_' || v_rk || '_' || norm(p_req) end;
  v_prev := t_req_get(v_key);
  if v_prev is not null then return v_prev; end if;

  -- بيع (أو رجوع للشركة): لازم يكون معاه رصيد كفاية من كل صنف
  if not v_ret or exists (select 1 from jsonb_array_elements(p_items) e where norm(e ->> 'returnKind') = 'رجوع للشركة') then
    v_bal := t_balances(u ->> 'name', u ->> 'branch');
    for r in
      select nm, sum(q) tq, min(o) o from (
        select norm(e ->> 'itemName') nm, coalesce(js_number(e -> 'qty'), 0) q, o
        from jsonb_array_elements(p_items) with ordinality x(e, o)
        where not v_ret or norm(e ->> 'returnKind') = 'رجوع للشركة') z
      where nm <> '' group by nm order by min(o)
    loop
      select coalesce(
        (select (b ->> 'balance')::numeric from jsonb_array_elements(v_bal) b
          where (select ic.code from t_item_by_name(r.nm) ic) <> '' and b ->> 'code' = (select ic.code from t_item_by_name(r.nm) ic) limit 1),
        (select (b ->> 'balance')::numeric from jsonb_array_elements(v_bal) b where norm(b ->> 'name') = r.nm limit 1),
        0) into v_av;
      if v_av < r.tq then
        v_short := v_short || (r.nm || ' (المتاح: ' || t_num_txt(v_av) || ' - المطلوب: ' || t_num_txt(r.tq) || ')');
      end if;
    end loop;
    if cardinality(v_short) > 0 then
      raise exception '%', 'في أصناف مش متاحة عندك بالكمية دي، راجع رصيدك من شاشة "أرصدتي": ' || array_to_string(v_short, '، ');
    end if;
  end if;

  -- نفس الفاتورة بالظبط اتسجلت النهارده؟
  if not coalesce(p_confirm, false) then
    select coalesce(jsonb_agg(jsonb_build_array(norm(e ->> 'itemName'), coalesce(js_number(e -> 'qty'), 0), coalesce(js_number(e -> 'price'), 0))
             order by norm(e ->> 'itemName'), coalesce(js_number(e -> 'qty'), 0), coalesce(js_number(e -> 'price'), 0)), '[]')
      into v_req_sorted from jsonb_array_elements(p_items) e where norm(e ->> 'returnKind') is distinct from 'رجوع للشركة';
    select sid into v_match from (
      select session_id sid, min(sheet_row) f,
        jsonb_agg(jsonb_build_array(item_name, abs(coalesce(qty, 0)), coalesce(price, 0)) order by item_name, abs(coalesce(qty, 0)), coalesce(price, 0)) sig
      from sales where rep_key = v_rk and day = v_today and session_id <> ''
        and (case when v_ret then coalesce(qty, 0) < 0 else coalesce(qty, 0) > 0 end)
      group by session_id) z
    where sig = v_req_sorted order by f limit 1;
    if v_match is not null then
      return jsonb_build_object('needsDuplicateConfirm', true, 'matchedSessionId', v_match);
    end if;
  end if;

  v_dup := t_most_similar(v_rk, v_today, v_ret,
    (select jsonb_agg(jsonb_build_object('name', norm(e ->> 'itemName'), 'qty', abs(coalesce(js_number(e -> 'qty'), 0)), 'price', coalesce(js_number(e -> 'price'), 0)) order by o)
       from jsonb_array_elements(p_items) with ordinality x(e, o) where norm(e ->> 'returnKind') is distinct from 'رجوع للشركة'), '');

  v_sid := t_short_id() || substr(md5(random()::text || clock_timestamp()::text), 1, 4);
  for it in select e from jsonb_array_elements(p_items) e loop
    n := n + 1;
    v_name := norm(it ->> 'itemName'); v_q := js_number(it -> 'qty'); v_p := js_number(it -> 'price');
    if v_name = '' or v_q is null or v_q <= 0 or v_p is null or v_p < 0 then
      raise exception 'من فضلك أكمل بيانات الأصناف بشكل صحيح قبل الترحيل';
    end if;
    select * into v_code from t_code_for(v_name);
    v_signed := case when v_ret then -v_q else v_q end;
    v_co := v_ret and norm(it ->> 'returnKind') = 'رجوع للشركة';
    v_reason := case when v_ret then left(norm(it ->> 'returnReason'), 300) else '' end;
    if v_co then
      -- رجوع للشركة: بضاعة راجعة من مخزون الفرع للشركة (مش من عميل) — توريد بالسالب، مش مبيعات ومش مرتجع عميل
      v_nco := v_nco + 1;
      insert into tawrid (sheet_row, code_raw, code, item_name, qty, rep, rep_key, day, branch_raw, branch, ts, src)
      values (1000000000 + n, v_code.code_raw, v_code.code, v_name, -v_q, u ->> 'name', v_rk, v_today, coalesce(u ->> 'branch', ''),
              coalesce((parse_branches(u ->> 'branch'))[1], ''), v_now, 'sb');
      v_items := v_items || jsonb_build_object('اسم الصنف', v_name, 'الكمية', -v_q, 'السعر', v_p, 'الاجمالي', 0,
                                               'نوع المرتجع', 'رجوع للشركة', 'سبب المرتجع', v_reason);
      continue;
    end if;
    v_nsales := v_nsales + 1;
    v_line := r2(v_signed * v_p);
    v_total := r2(v_total + v_line);
    v_kind := case when v_ret then (case when norm(it ->> 'returnKind') = 'تالف' then 'تالف' else 'سليم' end) else '' end;
    insert into sales (sheet_row, code_raw, code, rep, rep_key, day, item_name, qty, price, total, row_id, posted, col9, session_id,
                       branch_raw, branch, return_kind, ts, return_reason, src)
    values (1000000000 + n, v_code.code_raw, v_code.code, u ->> 'name', v_rk, v_today, v_name, v_signed, v_p, v_line, t_short_id(), 'true', '', v_sid,
            coalesce(u ->> 'branch', ''), coalesce((parse_branches(u ->> 'branch'))[1], ''), v_kind, v_now, v_reason, 'sb');
    v_items := v_items || (jsonb_build_object('اسم الصنف', v_name, 'الكمية', v_signed, 'السعر', v_p, 'الاجمالي', v_line)
      || case when v_ret then jsonb_build_object('نوع المرتجع', v_kind, 'سبب المرتجع', v_reason) else '{}'::jsonb end);
  end loop;
  if v_nsales > 0 then
    insert into sessions (sheet_row, session_id, rep, rep_key, day, posted, kind, branch_raw, branch, src)
    values (1000000000 + (extract(epoch from v_now)::bigint % 1000000000)::int, v_sid, u ->> 'name', v_rk, v_today, 'true', v_t, coalesce(u ->> 'branch', ''), coalesce((parse_branches(u ->> 'branch'))[1], ''), 'sb');
  else
    v_sid := 'cret_' || to_char(v_today, 'YYYY-MM-DD') || '@' || coalesce((parse_branches(u ->> 'branch'))[1], '');
  end if;

  v_res := jsonb_build_object('ok', true, 'sessionId', v_sid, 'date', dmy(v_today), 'repName', u ->> 'name', 'type', v_t,
                              'items', v_items, 'total', v_total, 'duplicate', v_dup);
  perform t_req_put(v_key, v_res);
  return v_res;
end $function$;

CREATE OR REPLACE FUNCTION public.t_grade(s numeric)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select case when s >= 85 then 'ممتاز' when s >= 70 then 'جيد جدًا' when s >= 55 then 'جيد' when s >= 40 then 'مقبول' else 'ضعيف' end
$function$;

CREATE OR REPLACE FUNCTION public.t_haversine_m(p_lat1 numeric, p_lng1 numeric, p_lat2 numeric, p_lng2 numeric)
 RETURNS numeric
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select case when p_lat1 is null or p_lng1 is null or p_lat2 is null or p_lng2 is null then null else
    round((6371000 * acos(least(1, greatest(-1,
      cos(radians(p_lat1)) * cos(radians(p_lat2)) * cos(radians(p_lng2) - radians(p_lng1)) +
      sin(radians(p_lat1)) * sin(radians(p_lat2))
    ))))::numeric, 0)
  end
$function$;

CREATE OR REPLACE FUNCTION public.t_home_stats(u jsonb)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  select jsonb_build_object(
    'today', r2(coalesce(sum(total) filter (where day = biz_today()), 0)),
    'todayLines', count(*) filter (where day = biz_today()),
    'month', r2(coalesce(sum(total), 0)))
  from sales
  where rep_key = rkey(u ->> 'name') and rkey(u ->> 'name') <> ''
    and day >= date_trunc('month', biz_today())::date and day < (date_trunc('month', biz_today()) + interval '1 month')::date
$function$;

CREATE OR REPLACE FUNCTION public.t_invoice_details(u jsonb, p_sid text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare
  v_sid text := norm(p_sid); v_rk text := rkey(u ->> 'name'); s sessions%rowtype; v_ret boolean; v_items jsonb; v_total numeric;
  v_ibr text; v_ub text[] := user_branches(u); v_jard boolean; v_key text; v_only text; v_m text[]; v_day date; v_lbl text; v_found text; v_cret boolean := false;
begin
  if v_sid = '' then raise exception 'رقم الفاتورة غير صحيح'; end if;
  if v_sid like 'jard\_%' or v_sid like 'tawrid\_%' or v_sid like 'cret\_%' then
    v_jard := v_sid like 'jard\_%';
    v_cret := v_sid like 'cret\_%';
    v_key := substr(v_sid, case when v_jard or v_cret then 6 else 8 end);
    if position('@' in v_key) > 0 then
      v_only := substr(v_key, position('@' in v_key) + 1);
      v_key := substr(v_key, 1, position('@' in v_key) - 1);
    end if;
    v_m := regexp_match(v_key, '^([0-9]{4})-([0-9]{2})-([0-9]{2})$');
    if v_m is null then raise exception 'رقم الفاتورة غير صحيح'; end if;
    v_day := make_date(v_m[1]::int, 1, 1) + make_interval(months => v_m[2]::int - 1, days => v_m[3]::int - 1);
    v_lbl := case when v_jard then 'العدد' else 'الكمية' end;
    with rows as (
      select sheet_row, item_name, coalesce(case when v_jard then count else qty end, 0) q,
             coalesce(nullif(branch, ''), case when cardinality(v_ub) > 1 then coalesce(v_ub[1], '') else '' end) rb
      from (select sheet_row, item_name, count, null::numeric qty, branch from jard where v_jard and rep_key = v_rk and day = v_day
            union all select sheet_row, item_name, null, qty, branch from tawrid where not v_jard and rep_key = v_rk and day = v_day
              and (case when v_cret then coalesce(qty, 0) < 0 else coalesce(qty, 0) >= 0 end)) x
    ), f as (
      select * from rows where v_only is null or (case when v_only <> '' then rkey(rb) = rkey(v_only) else rb = '' end)
    )
    select jsonb_agg(jsonb_build_object('اسم الصنف', item_name, v_lbl, q) order by sheet_row), sum(q),
           (array_agg(rb order by sheet_row))[1]
      into v_items, v_total, v_found from f;
    if v_items is null then raise exception 'مفيش أصناف متسجلة لهذا اليوم'; end if;
    return jsonb_build_object('ok', true, 'sessionId', v_sid, 'date', dmy(v_day), 'repName', u ->> 'name',
      'branch', coalesce(nullif(v_only, ''), v_found, ''), 'type', case when v_jard then 'جرد' when v_cret then 'رجوع للشركة' else 'توريد' end,
      'qtyLabel', v_lbl, 'items', v_items, 'total', v_total);
  end if;

  select * into s from sessions where session_id = v_sid order by sheet_row limit 1;
  if not found then raise exception 'الفاتورة دي مش موجودة'; end if;
  if s.rep_key <> v_rk then raise exception 'غير مصرح لك بمشاهدة هذه الفاتورة'; end if;
  v_ret := s.kind = 'مرتجع';
  select jsonb_agg(jsonb_build_object('اسم الصنف', item_name, 'الكمية', coalesce(qty, 0), 'السعر', coalesce(price, 0), 'الاجمالي', coalesce(total, 0))
           || case when v_ret then jsonb_build_object('نوع المرتجع', case when return_kind = 'تالف' then 'تالف' else 'سليم' end, 'سبب المرتجع', return_reason) else '{}'::jsonb end
           order by sheet_row),
         sum(coalesce(total, 0)), (array_agg(branch order by sheet_row) filter (where branch <> ''))[1]
    into v_items, v_total, v_ibr
    from sales where session_id = v_sid and rep_key = v_rk;
  if v_items is null then raise exception 'مفيش أصناف متسجلة لهذه الفاتورة'; end if;
  return jsonb_build_object('ok', true, 'sessionId', v_sid, 'date', coalesce(dmy(s.day), ''), 'repName', u ->> 'name',
    'branch', coalesce(nullif(s.branch, ''), v_ibr, case when cardinality(v_ub) > 1 then v_ub[1] else '' end),
    'type', case when v_ret then 'مرتجع' else 'بيع' end, 'items', v_items, 'total', v_total,
    'duplicate', case when s.day is null then null else t_most_similar(v_rk, s.day, v_ret,
        (select jsonb_agg(jsonb_build_object('name', e ->> 'اسم الصنف', 'qty', abs((e ->> 'الكمية')::numeric), 'price', (e -> 'السعر')) order by o)
           from jsonb_array_elements(v_items) with ordinality x(e, o)), v_sid) end);
end $function$;

CREATE OR REPLACE FUNCTION public.t_item_by_name(p_name text)
 RETURNS TABLE(code_raw text, code text)
 LANGUAGE sql
 STABLE
AS $function$
  select norm(jtxt(raw -> 'الكود')), code from items where name = norm(p_name) order by sheet_row limit 1
$function$;

CREATE OR REPLACE FUNCTION public.t_item_sales(u jsonb, p_target text, p_month text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare
  v_all boolean := coalesce((u ->> 'isAdmin')::boolean, false) and norm(p_target) = '__ALL__';
  v_pick jsonb := pick_target(u, case when v_all then '' else p_target end);
  v_name text; v_rk text; v_rks text[]; v_mk text := norm(p_month); v_m0 date; v_items jsonb; v_months jsonb;
  v_tq numeric; v_tv numeric; v_allowed jsonb := u -> 'allowedBranches';
begin
  if v_all then
    v_name := '__ALL__';
    select coalesce(array_agg(rep_key), '{}') into v_rks from reps where not is_admin and branches_allowed(branch_raw, v_allowed);
  else
    v_name := v_pick ->> 'target'; v_rk := rkey(v_name); v_rks := array[v_rk];
  end if;
  if v_mk !~ '^[0-9]{4}-[0-9]{2}$' then v_mk := t_month_key(biz_today()); end if;
  v_m0 := make_date(split_part(v_mk, '-', 1)::int, 1, 1) + make_interval(months => split_part(v_mk, '-', 2)::int - 1);
  with r as (
    select sheet_row, item_name, code_raw, coalesce(qty, 0) q, coalesce(total, 0) t, day from sales
    where rep_key = any(v_rks) and day >= v_m0 and day < (v_m0 + interval '1 month')::date and item_name <> ''
    and to_char(day, 'YYYY-MM') = v_mk
  ), g as (
    select item_name, min(sheet_row) f,
      coalesce((array_agg(code_raw order by sheet_row) filter (where code_raw <> ''))[1], '') code,
      sum(q) filter (where q >= 0) sold, -sum(q) filter (where q < 0) ret, count(*) filter (where q >= 0) cnt,
      sum(t) val, max(day) filter (where q >= 0) last
    from r group by item_name
  ), it as (
    select item_name, f, code, r2(coalesce(sold, 0)) sold, r2(coalesce(ret, 0)) ret, r2(coalesce(sold, 0) - coalesce(ret, 0)) net, cnt, r2(val) val, last from g
  )
  select coalesce(jsonb_agg(jsonb_build_object('code', code, 'name', item_name, 'soldQty', sold, 'returnedQty', ret, 'netQty', net,
           'salesCount', cnt, 'value', val, 'lastSaleDate', coalesce(dmy(last), '')) order by net desc, f), '[]'),
         r2(coalesce(sum(net), 0)), r2(coalesce(sum(val), 0))
    into v_items, v_tq, v_tv from it;
  select coalesce(jsonb_agg(m order by m desc), '[]') into v_months
    from (select distinct to_char(day, 'YYYY-MM') m from sales where rep_key = any(v_rks) and day is not null) x;
  if not v_months @> to_jsonb(v_mk) then v_months := jsonb_build_array(v_mk) || v_months; end if;
  return jsonb_build_object('user', u, 'repName', v_name, 'reps', v_pick -> 'reps', 'monthKey', v_mk, 'months', v_months,
    'items', v_items, 'totals', jsonb_build_object('netQty', v_tq, 'value', v_tv));
end
$function$;

CREATE OR REPLACE FUNCTION public.t_list_asnaf(u jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare res jsonb;
begin
  if not coalesce((u ->> 'isAdmin')::boolean, false) then raise exception 'غير مصرح لك بعرض الأصناف'; end if;
  select coalesce(jsonb_agg(jsonb_build_object('code', code, 'name', name, 'season', coalesce(raw ->> 'الموسم', '')) order by name collate ar_sort, sheet_row), '[]')
    into res from items where name <> '';
  return res;
end
$function$;

CREATE OR REPLACE FUNCTION public.t_list_branches(p_allowed jsonb)
 RETURNS text[]
 LANGUAGE sql
 STABLE
AS $function$
  select coalesce(array_agg(b order by b collate ar_sort, b), '{}') from (
    select distinct b from reps, unnest(parse_branches(branch_raw)) b) x
  where branch_allowed(b, p_allowed)
$function$;

CREATE OR REPLACE FUNCTION public.t_list_invoices(u jsonb, p_opts jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare
  v_lim numeric := js_number(p_opts -> 'limit'); v_limit int; v_rk text := rkey(u ->> 'name'); v_ub text[] := user_branches(u);
  v_multi boolean; v_first text; res jsonb; v_show boolean;
begin
  v_limit := case when v_lim > 0 then least(200, trunc(v_lim))::int else 30 end;
  v_multi := cardinality(v_ub) > 1;
  v_first := coalesce(v_ub[1], nullif(u ->> 'branch', ''), '');
  with ss as (
    select s.sheet_row, s.session_id sid, s.day, case when s.kind = 'مرتجع' then 'مرتجع' else 'بيع' end typ, s.branch
    from sessions s where s.rep_key = v_rk and s.session_id <> ''
  ), agg as (
    select session_id sid, count(*) n, sum(coalesce(total, 0)) tot,
           (array_agg(branch order by sheet_row) filter (where branch <> ''))[1] br
    from sales where rep_key = v_rk and session_id in (select sid from ss) group by session_id
  ), e as (
    select ss.sid, ss.day, ss.typ, coalesce(a.n, 0) n, r2(coalesce(a.tot, 0)) tot, null::numeric tq,
           coalesce(nullif(ss.branch, ''), nullif(a.br, ''), case when v_multi then v_first else '' end) br,
           1 grp, ss.sheet_row::bigint ord
    from ss left join agg a on a.sid = ss.sid
    union all
    select 'jard_' || to_char(day, 'YYYY-MM-DD') || '@' || rb, day, 'جرد', count(*), null, sum(coalesce(count, 0)), rb, 2, min(sheet_row)
    from (select *, coalesce(nullif(branch, ''), case when v_multi then v_first else '' end) rb from jard where rep_key = v_rk and day is not null) j
    group by day, rb
    union all
    select 'tawrid_' || to_char(day, 'YYYY-MM-DD') || '@' || rb, day, 'توريد', count(*), null, sum(coalesce(qty, 0)), rb, 3, min(sheet_row)
    from (select *, coalesce(nullif(branch, ''), case when v_multi then v_first else '' end) rb from tawrid where rep_key = v_rk and day is not null and coalesce(qty, 0) >= 0) t
    group by day, rb
    union all
    select 'cret_' || to_char(day, 'YYYY-MM-DD') || '@' || rb, day, 'رجوع للشركة', count(*), null, sum(coalesce(qty, 0)), rb, 4, min(sheet_row)
    from (select *, coalesce(nullif(branch, ''), case when v_multi then v_first else '' end) rb from tawrid where rep_key = v_rk and day is not null and coalesce(qty, 0) < 0) t
    group by day, rb
  ), top as (
    select * from e order by day desc nulls last, grp, ord limit v_limit
  )
  select coalesce(jsonb_agg(jsonb_build_object('sessionId', sid, 'date', coalesce(dmy(day), ''), 'type', typ, 'itemCount', n,
           'total', tot, 'totalQty', tq, 'branch', coalesce(br, '')) order by day desc nulls last, grp, ord), '[]'),
         count(distinct nar(br)) filter (where nar(br) <> '') > 1
    into res, v_show from top;
  return jsonb_build_object('user', u, 'invoices', res, 'multiBranch', v_multi, 'showBranch', v_multi or v_show);
end $function$;

CREATE OR REPLACE FUNCTION public.t_list_products()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  select coalesce(jsonb_agg(jsonb_build_object(
      'id', norm(jtxt(raw -> 'المعرف')), 'name', norm(jtxt(raw -> 'اسم المنتج')),
      'specs', case when raw -> 'المواصفات' is null or jsonb_typeof(raw -> 'المواصفات') = 'null' or (raw ->> 'المواصفات') = '' then '' else norm_lines(jtxt(raw -> 'المواصفات')) end,
      'photos', coalesce((select case when jsonb_typeof(j) = 'array' then j end from (select safe_jsonb(coalesce(nullif(norm(jtxt(raw -> 'الصور')), ''), '[]')) j) q), '[]'),
      'date', coalesce(dmy(psd(raw -> 'تاريخ الإضافة')), ''), '_rowNumber', sheet_row) order by sheet_row desc), '[]')
  from product_desc
$function$;

CREATE OR REPLACE FUNCTION public.t_list_reps(u jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare res jsonb;
begin
  if not is_owner(u) then raise exception 'غير مصرح لك بعرض المناديب'; end if;
  select coalesce(jsonb_agg(jsonb_build_object('name', name, 'email', email, 'branch', branch_raw, 'isAdmin', is_admin,
           'isProtected', email = 'elzenoukisales@gmail.com', 'supervisors', to_jsonb(split_sups(jtxt(raw -> 'المشرف المسؤول'))),
           'fullName', nullif(raw ->> 'الاسم الكامل', ''), 'jobCode', nullif(raw ->> 'الكود الوظيفي', ''))
           order by name collate ar_sort, sheet_row), '[]')
    into res from reps where email <> '';
  return res;
end $function$;

CREATE OR REPLACE FUNCTION public.t_list_suggestions(u jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare res jsonb;
begin
  if not is_owner(u) then raise exception 'غير مصرح لك بعرض المقترحات'; end if;
  select coalesce(jsonb_agg(jsonb_build_object(
      'date', coalesce(dmy(psd(raw -> 'التاريخ')), norm(jtxt(raw -> 'التاريخ'))),
      'repName', norm(jtxt(raw -> 'اسم المندوب')), 'text', norm(jtxt(raw -> 'النص')), '_rowNumber', sheet_row) order by sheet_row desc), '[]')
    into res from suggestions;
  return res;
end $function$;

CREATE OR REPLACE FUNCTION public.t_month_key(d date)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$ select to_char(d, 'YYYY-MM') $function$;

CREATE OR REPLACE FUNCTION public.t_most_similar(p_rk text, p_day date, p_ret boolean, p_items jsonb, p_exclude text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare r record; v_pct numeric; best jsonb; best_pct int;
begin
  for r in
    select session_id sid, min(sheet_row) f,
      jsonb_agg(jsonb_build_object('name', item_name, 'qty', abs(coalesce(qty, 0)), 'price', coalesce(price, 0)) order by sheet_row) its,
      (array_agg(ts order by sheet_row) filter (where ts is not null))[1] ts
    from sales where rep_key = p_rk and day = p_day and session_id <> '' and session_id <> p_exclude
      and (case when p_ret then coalesce(qty, 0) < 0 else coalesce(qty, 0) > 0 end)
    group by session_id order by f
  loop
    v_pct := t_similarity(p_items, r.its);
    if v_pct >= 0.8 and (best is null or r0(v_pct * 100) > best_pct) then
      best_pct := r0(v_pct * 100)::int;
      best := jsonb_build_object('sessionId', r.sid, 'pct', best_pct,
                                 'time', coalesce(to_char(r.ts at time zone 'Africa/Cairo', 'HH24:MI'), ''));
    end if;
  end loop;
  return best;
exception when others then return null;
end $function$;

CREATE OR REPLACE FUNCTION public.t_ms_split(v_sb text[], p_day date)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare res jsonb;
begin
  with base as (select * from _ms where p_day is null or day = p_day),
  keys as (select rb, min(sheet_row) f from base where rb <> '' group by rb),
  extra as (select k.rb, k.f from keys k where not exists (select 1 from unnest(v_sb) b where rkey(b) = rkey(k.rb))),
  extra1 as (select distinct on (rkey(rb)) rb, f from extra order by rkey(rb), f),
  names as (select b, o::bigint ord from unnest(v_sb) with ordinality x(b, o) union all select rb, 1000000000 + f from extra1)
  select coalesce(jsonb_agg(jsonb_build_object('branch', b, 'total',
           r2((select coalesce(sum(total), 0) from base where rkey(base.rb) = rkey(names.b)))) order by ord), '[]')
    into res from names;
  return res;
end $function$;

CREATE OR REPLACE FUNCTION public.t_my_prices(p_email text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  select coalesce(jsonb_object_agg(item_name, p order by sheet_row), '{}') from (
    select item_name, js_number(raw -> 'السعر') p, sheet_row from prices where email = p_email and item_name <> '') x
  where p is not null
$function$;

CREATE OR REPLACE FUNCTION public.t_my_stats(u jsonb, p_target text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare
  v_today date := biz_today(); v_m0 date; v_m1 date; v_pick jsonb; v_name text; v_rk text; v_sb text[];
  v_month numeric; v_today_t numeric; v_ml int; v_tl int; v_t numeric; v_pct numeric; v_off int[]; v_daily jsonb; v_wd jsonb;
  v_cdays int; v_split_t jsonb; v_split_m jsonb; v_blk jsonb;
begin
  if not coalesce((u ->> 'isAdmin')::boolean, false) then
    v_blk := t_block_items(u);
    if jsonb_array_length(v_blk) > 0 then
      return jsonb_build_object('user', u, 'isAdmin', false, 'blocked', true, 'blockItems', v_blk, 'blockWindowDays', 30);
    end if;
  end if;
  v_pick := pick_target(u, p_target);
  v_name := v_pick ->> 'target'; v_rk := rkey(v_name);
  v_m0 := date_trunc('month', v_today)::date; v_m1 := (v_m0 + interval '1 month')::date;
  v_sb := rep_branches(v_name);

  create temp table if not exists _ms (sheet_row int, day date, total numeric, rb text) on commit drop;
  truncate _ms;
  insert into _ms select sheet_row, day, coalesce(total, 0), coalesce(nullif(branch, ''), v_sb[1], '')
    from sales where rep_key = v_rk and day >= v_m0 and day < v_m1;

  select coalesce(sum(total), 0), count(*) into v_month, v_ml from _ms;
  select coalesce(sum(total), 0), count(*) into v_today_t, v_tl from _ms where day = v_today;

  -- تقسيم على الفروع (لمندوب ماسك أكتر من فرع)
  if cardinality(v_sb) >= 2 then
    v_split_t := t_ms_split(v_sb, v_today);
    v_split_m := t_ms_split(v_sb, null);
  else
    v_split_t := '[]'; v_split_m := '[]';
  end if;

  v_t := t_target_row(v_name, t_month_key(v_today));
  if v_t is not null then v_pct := greatest(0, r1(v_month / v_t * 100)); end if;

  v_off := coalesce(array(
    select array_position(array['الأحد','الإثنين','الثلاثاء','الأربعاء','الخميس','الجمعة','السبت'], d) - 1
    from unnest(t_weekly_off(jtxt((select raw -> 'الإجازة الأسبوعية' from reps where rep_key = v_rk and v_rk <> '' order by sheet_row limit 1)))) d), '{}');

  with cd as (
    select distinct extract(day from day)::int d from sales where day >= v_m0 and day <= v_today
  ), dd as (
    select g::int d, extract(dow from make_date(extract(year from v_today)::int, extract(month from v_today)::int, g::int))::int wd,
      (select case when count(*) > 0 then r2(sum(total)) end from _ms where extract(day from _ms.day) = g and _ms.day <= v_today) t
    from generate_series(1, extract(day from v_today)::int) g
  ), w as (
    select wd, sum(coalesce(t, 0)) s, count(*) n from dd where d in (select d from cd) and not (wd = any(v_off)) group by wd
  )
  select
    (select coalesce(jsonb_agg(jsonb_build_object('d', d, 'wd', wd, 'total', coalesce(t, 0), 'sold', t is not null) order by d), '[]') from dd),
    (select jsonb_agg(jsonb_build_object('wd', g, 'avg', case when w.n > 0 then r0(w.s / w.n) else null end, 'days', coalesce(w.n, 0)) order by g)
       from generate_series(0, 6) g left join w on w.wd = g),
    (select count(*) from cd)
  into v_daily, v_wd, v_cdays;

  return jsonb_build_object(
    'user', u, 'repName', v_name, 'reps', v_pick -> 'reps',
    'today', jsonb_build_object('date', dmy(v_today), 'total', r2(v_today_t), 'linesCount', v_tl, 'byBranch', v_split_t),
    'pulse', jsonb_build_object('year', extract(year from v_today)::int, 'month', extract(month from v_today)::int,
                                'daily', v_daily, 'weekdays', v_wd, 'companyDays', v_cdays),
    'month', jsonb_build_object('total', r2(v_month), 'linesCount', v_ml, 'monthLabel', to_char(v_today, 'MM/YYYY'),
                                'byBranch', v_split_m, 'target', v_t, 'targetPct', v_pct));
end $function$;

CREATE OR REPLACE FUNCTION public.t_next_row(p_table text)
 RETURNS integer
 LANGUAGE plpgsql
AS $function$
declare n integer;
begin
  execute format('select coalesce(max(sheet_row), 1) + 1 from public.%I', p_table) into n;
  return n;
end $function$;

CREATE OR REPLACE FUNCTION public.t_num_txt(n numeric)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$ select trim_scale(n)::text $function$;

CREATE OR REPLACE FUNCTION public.t_profile(u jsonb)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  select jsonb_build_object('user', u, 'profile', jsonb_build_object(
      'photoUrl', norm(jtxt(r.raw -> 'الصورة')),
      'age', nullif(coalesce(js_number(r.raw -> 'السن'), 0), 0),
      'experienceYears', nullif(coalesce(js_number(r.raw -> 'سنوات الخبرة'), 0), 0),
      'weeklyOff', to_jsonb(t_weekly_off(jtxt(r.raw -> 'الإجازة الأسبوعية')))),
    'weeklyOffOptions', jsonb_build_array('الأحد','الإثنين','الثلاثاء','الأربعاء','الخميس','الجمعة','السبت'))
  from (select null) d left join lateral (select raw from reps where email = u ->> 'email' order by sheet_row limit 1) r on true
$function$;

CREATE OR REPLACE FUNCTION public.t_rep_eval_month(p_mk text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare
  cfg jsonb := ev2_cfg();
  v_m0 date := make_date(split_part(p_mk, '-', 1)::int, split_part(p_mk, '-', 2)::int, 1);
  v_m1 date := (make_date(split_part(p_mk, '-', 1)::int, split_part(p_mk, '-', 2)::int, 1) + interval '1 month')::date;
  v_today date := biz_today();
  v_end date; v_b0 date;
  v_season float8; v_cdays int; v_weeks int; v_stmed float8; v_mindays int;
  r record; b text; lst jsonb; bal jsonb; v_rc text[];
  v_rk text; v_stale int; v_unres int; v_carried int; v_first date; v_new boolean; v_endstock numeric;
  v_g3 numeric; v_rt3 numeric; v_g numeric; v_rt numeric; v_dm numeric; v_co numeric; v_nd int; v_sq numeric; v_jw int;
  v_off text[]; v_expdays int; v_attdays int;
  res jsonb;
begin
  v_end := least(v_m1 - 1, v_today);
  v_b0 := (v_m0 - make_interval(months => (cfg ->> 'base_months')::int))::date;
  if v_end < v_m0 then
    return jsonb_build_object('mk', p_mk, 'season', 1, 'workDays', 0, 'weeks', 0, 'stMedian', null, 'rows', '[]'::jsonb);
  end if;
  v_weeks := ceil((v_end - v_m0 + 1) / 7.0)::int;

  drop table if exists _days2;
  create temp table _days2 on commit drop as
  select d::date d, (array['الأحد','الإثنين','الثلاثاء','الأربعاء','الخميس','الجمعة','السبت'])[extract(dow from d)::int + 1] dname
  from generate_series(v_m0, v_end, interval '1 day') g(d);

  drop table if exists _s2;
  create temp table _s2 on commit drop as
  select s.rep_key rk, s.day, coalesce(s.total, 0)::numeric total, coalesce(s.qty, 0)::numeric qty,
         coalesce(s.return_kind, '') rkind,
         case when coalesce(s.branch, '') <> '' then s.branch_key else coalesce(rkey(fb.fb), '') end bk
  from sales s left join rep_first_branch_map() fb on fb.rep_key = s.rep_key
  where coalesce(s.rep_key, '') <> '' and s.day >= v_b0 and s.day < v_m1;

  select count(distinct day) into v_cdays from _s2 where qty > 0 and day >= v_m0;
  v_mindays := least((cfg ->> 'min_days')::int, ceil(coalesce(v_cdays, 0) * 0.5)::int);

  drop table if exists _bb2;
  create temp table _bb2 on commit drop as
  select bk, sum(total)::float8 / count(distinct day) pd
  from _s2 where qty > 0 and day < v_m0 and bk <> ''
  group by bk having count(distinct day) >= (cfg ->> 'base_min_days')::int;

  select sum(c.pd) / nullif(sum(bb.pd), 0) into v_season
  from _bb2 bb join (
    select bk, sum(total)::float8 / count(distinct day) pd from _s2 where qty > 0 and day >= v_m0 and bk <> '' group by bk
  ) c on c.bk = bb.bk;
  v_season := coalesce(nullif(v_season, 0), 1);

  drop table if exists _rd2;
  create temp table _rd2 on commit drop as
  select rk, bk, count(distinct day) nd, sum(total) tot from _s2 where qty > 0 and day >= v_m0 group by rk, bk;

  drop table if exists _ev2;
  create temp table _ev2 (i int, name text, rk text, branches text[], gross numeric, ret numeric, dmg numeric, co numeric, net numeric,
    target numeric, stale int, unres int, carried int, is_new boolean, days int, sold numeric, endstock numeric, jw int,
    gross3 numeric, ret3 numeric, expdays int, attdays int) on commit drop;

  for r in
    select row_number() over (order by sheet_row) i, name, rep_key, parse_branches(branch_raw) br, raw ->> 'الإجازة الأسبوعية' off_raw
    from reps where name <> '' and not is_admin order by sheet_row
  loop
    v_rk := coalesce(nullif(r.rep_key, ''), rkey(r.name));
    select coalesce(sum(case when qty > 0 then total else 0 end), 0),
           coalesce(sum(case when qty < 0 and rkind not in ('تالف', 'رجوع للشركة') then abs(total) else 0 end), 0),
           coalesce(sum(case when qty < 0 and rkind = 'تالف' then abs(total) else 0 end), 0),
           coalesce(sum(case when qty < 0 and rkind = 'رجوع للشركة' then abs(total) else 0 end), 0),
           count(distinct day) filter (where qty > 0),
           coalesce(sum(qty) filter (where qty > 0), 0)
      into v_g, v_rt, v_dm, v_co, v_nd, v_sq
      from _s2 where rk = v_rk and day >= v_m0;
    if cardinality(r.br) = 0 and v_g = 0 and v_rt = 0 then continue; end if;
    select coalesce(sum(case when qty > 0 then total else 0 end), 0),
           coalesce(sum(case when qty < 0 and rkind not in ('تالف', 'رجوع للشركة') then abs(total) else 0 end), 0)
      into v_g3, v_rt3
      from _s2 where rk = v_rk and day >= (v_m0 - interval '2 months')::date;
    select count(distinct day) into v_jw from jard where rep_key = v_rk and day >= v_m0 and day <= v_end;
    if v_g = 0 and v_rt = 0 and coalesce(v_jw, 0) = 0 then continue; end if;

    v_off := t_weekly_off(coalesce(r.off_raw, ''));
    select count(*) into v_expdays from _days2 where not (dname = any(v_off));
    select count(distinct d) into v_attdays from (
      select day d from _s2 where rk = v_rk and day >= v_m0 and day <= v_end
      union select day from jard where rep_key = v_rk and day >= v_m0 and day <= v_end
      union select day from tawrid where rep_key = v_rk and day >= v_m0 and day <= v_end
    ) z;

    select min(d) into v_first from (
      select min(day) d from jard where rep_key = v_rk
      union all select min(day) from tawrid where rep_key = v_rk
      union all select min(day) from sales where rep_key = v_rk) z;
    v_new := v_first is null or (v_end - v_first) < 30;

    v_carried := 0; v_endstock := 0;
    foreach b in array (case when cardinality(r.br) = 0 then array[''] else r.br end) loop
      begin
        bal := t_balances(r.name, b);
        select v_carried + count(*) into v_carried from jsonb_array_elements(bal) e where (e ->> 'balance')::numeric > 0;
        if v_end < v_today then bal := t_balances_asof(r.name, b, v_end); end if;
        select v_endstock + coalesce(sum(greatest((e ->> 'balance')::numeric, 0)), 0) into v_endstock from jsonb_array_elements(bal) e;
      exception when others then null; end;
      exit when cardinality(r.br) <= 1;
    end loop;

    v_stale := 0; v_unres := 0;
    foreach b in array r.br loop
      begin lst := t_stale(b, 21, 500, r.name); exception when others then lst := '[]'; end;
      v_stale := v_stale + jsonb_array_length(lst);
      select coalesce(array_agg(sr.code), '{}') into v_rc from stale_reasons sr
        where sr.code <> '' and exists (select 1 from unnest(parse_branches(sr.branch)) x where nar(x) = nar(b));
      select v_unres + count(*) into v_unres from jsonb_array_elements(lst) e
        where (e ->> 'days')::int >= 30 and not (norm(e ->> 'code') = any(v_rc));
    end loop;

    insert into _ev2 values (r.i, r.name, v_rk, r.br, r2(v_g), r2(v_rt), r2(v_dm), r2(v_co), r2(v_g - v_rt - v_dm),
      (select t from (select target t, sheet_row from targets where month_key = p_mk and rep <> '' and target > 0 and rep_key = rkey(r.name)
                      order by sheet_row desc limit 1) z),
      v_stale, v_unres, v_carried, v_new, coalesce(v_nd, 0), v_sq, v_endstock, coalesce(v_jw, 0), r2(v_g3), r2(v_rt3),
      greatest(coalesce(v_expdays, 0), 1), coalesce(v_attdays, 0));
  end loop;

  select percentile_cont(0.5) within group (order by sold::float8 / (sold + endstock)) into v_stmed
  from _ev2 where sold > 0 and endstock > 0 and days >= v_mindays;

  with pf as (
    select d.rk, sum(d.tot)::float8 tot, sum(d.nd * bb.pd * v_season) exp, sum(d.nd) nd
    from _rd2 d join _bb2 bb on bb.bk = d.bk group by d.rk
  ), base as (
    select e.*, e.days < v_mindays few_days,
      case when pf.exp > 0 then pf.tot / pf.exp end pr,
      case when pf.nd > 0 then pf.tot / pf.nd end pday,
      case when pf.nd > 0 then pf.exp / pf.nd end eday,
      case when e.target is not null then greatest(0, r1((e.net / e.target * 100)::numeric)) end tpct,
      case when e.sold > 0 and e.endstock > 0 then e.sold::float8 / (e.sold + e.endstock) end st
    from _ev2 e left join pf on pf.rk = e.rk
  ), sc as (
    select base.*,
      case when pr is not null then (cfg ->> 'w_perf')::float8 * least(pr / (cfg ->> 'perf_full')::float8, 1) end s_perf,
      case when tpct is not null then (cfg ->> 'w_target')::float8 * least(tpct, 100) / 100 end s_target,
      case when st is not null and coalesce(v_stmed, 0) > 0 then (cfg ->> 'w_sell')::float8 * least(st / (v_stmed * (cfg ->> 'sell_full')::float8), 1) end s_sell,
      case when is_new then null
           else (cfg ->> 'w_stale')::float8 * greatest(0, 1 - ((stale + unres)::float8 / greatest(carried, stale, 1)) / (cfg ->> 'stale_zero')::float8) end s_stale,
      case when gross3 < (cfg ->> 'ret_min_gross')::numeric then null
           else (cfg ->> 'w_ret')::float8 * greatest(0, 1 - (ret3::float8 / gross3::float8) / (cfg ->> 'ret_zero')::float8) end s_ret,
      (cfg ->> 'w_commit')::float8 * least(attdays::float8 / greatest(expdays, 1), 1) s_commit
    from base
  ), fin as (
    select sc.*,
      coalesce(s_perf, 0) + coalesce(s_target, 0) + coalesce(s_sell, 0) + coalesce(s_stale, 0) + coalesce(s_ret, 0) + s_commit got,
      case when s_perf is null then 0 else (cfg ->> 'w_perf')::float8 end
      + case when s_target is null then 0 else (cfg ->> 'w_target')::float8 end
      + case when s_sell is null then 0 else (cfg ->> 'w_sell')::float8 end
      + case when s_stale is null then 0 else (cfg ->> 'w_stale')::float8 end
      + case when s_ret is null then 0 else (cfg ->> 'w_ret')::float8 end
      + (cfg ->> 'w_commit')::float8 mx
    from sc
  )
  , fin2 as (
    select fin.*, few_days or (s_perf is null and s_target is null) incomplete from fin
  )
  select jsonb_build_object(
    'mk', p_mk, 'season', r2(v_season::numeric), 'workDays', coalesce(v_cdays, 0), 'weeks', v_weeks, 'minDays', v_mindays,
    'stMedian', case when v_stmed is null then null else r1((v_stmed * 100)::numeric) end,
    'rows', coalesce(jsonb_agg(jsonb_build_object(
      'name', name, 'branches', to_jsonb(branches), 'gross', gross, 'ret', ret, 'net', net, 'retDamaged', dmg, 'retCompany', co,
      'target', target, 'targetPct', tpct, 'days', days, 'incomplete', incomplete,
      'perDay', case when pday is null then null else r0(pday::numeric) end,
      'expPerDay', case when eday is null then null else r0(eday::numeric) end,
      'perfPct', case when pr is null then null else r0((pr * 100)::numeric) end,
      'sold', sold, 'endStock', endstock, 'sellPct', case when st is null then null else r1((st * 100)::numeric) end,
      'stale', stale, 'unresolved', unres, 'carried', carried, 'isNew', is_new,
      'retRate', case when gross > 0 then r1((ret / gross * 100)::numeric) else 0 end,
      'retRate3', case when gross3 > 0 then r1((ret3 / gross3 * 100)::numeric) else 0 end, 'gross3', gross3,
      'fewDays', few_days,
      'presentDays', attdays, 'expectedDays', expdays,
      'parts', jsonb_build_object(
        'perf', case when s_perf is null then null else jsonb_build_object('score', r1(s_perf::numeric), 'max', (cfg ->> 'w_perf')::int) end,
        'target', case when s_target is null then null else jsonb_build_object('score', r1(s_target::numeric), 'max', (cfg ->> 'w_target')::int) end,
        'sell', case when s_sell is null then null else jsonb_build_object('score', r1(s_sell::numeric), 'max', (cfg ->> 'w_sell')::int) end,
        'stale', case when s_stale is null then null else jsonb_build_object('score', r1(s_stale::numeric), 'max', (cfg ->> 'w_stale')::int) end,
        'returns', case when s_ret is null then null else jsonb_build_object('score', r1(s_ret::numeric), 'max', (cfg ->> 'w_ret')::int) end,
        'commit', jsonb_build_object('score', r1(s_commit::numeric), 'max', (cfg ->> 'w_commit')::int)),
      'score', r0((got / mx * 100)::numeric)) order by got / mx desc), '[]'))
  into res from fin2;
  return res;
end $function$;

CREATE OR REPLACE FUNCTION public.t_rep_eval_month_cached(p_mk text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare d jsonb; v_ttl interval;
begin
  v_ttl := case when p_mk < to_char(biz_today(), 'YYYY-MM') then interval '6 hours' else interval '10 minutes' end;
  select data into d from eval_cache where mk = 'v2m:' || p_mk and at > now() - v_ttl;
  if d is not null then return d; end if;
  d := t_rep_eval_month(p_mk);
  insert into eval_cache (mk, at, data) values ('v2m:' || p_mk, now(), d)
    on conflict (mk) do update set at = excluded.at, data = excluded.data;
  return d;
end $function$;

CREATE OR REPLACE FUNCTION public.t_rep_evaluations(p_mk text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare
  v_m0 date := make_date(split_part(p_mk, '-', 1)::int, split_part(p_mk, '-', 2)::int, 1);
  r record; b text; lst jsonb; v_stale int; v_unres int; v_avg float8; res jsonb; v_rc text[]; v_carried int; v_first date; v_new boolean;
  v_ref date := least((make_date(split_part(p_mk, '-', 1)::int, split_part(p_mk, '-', 2)::int, 1) + interval '1 month' - interval '1 day')::date, biz_today());
begin
  -- ret = مرتجع العملاء السليم بس (اللي بيتحسب في التقييم)، dmg = المرتجع التالف (عيب صناعة — مش بيتحسب على المندوب)
  -- is_new = أول حركة ليه (جرد/توريد/بيع) من أقل من 30 يوم → الرواكد مش بتتحسب عليه والتقييم بيتحسب من الباقي
  drop table if exists _ev;
  create temp table _ev (i int, name text, rk text, branches text[], gross numeric, ret numeric, net numeric,
    target numeric, stale int, unresolved int, details jsonb, dmg numeric, carried int, is_new boolean) on commit drop;
  truncate _ev;
  create temp table if not exists _iq (rk text, code text, q numeric, f int) on commit drop;
  truncate _iq;
  insert into _iq select rep_key, code, sum(coalesce(qty, 0)), min(sheet_row) from sales
    where rep_key <> '' and code <> '' and day >= v_m0 and day < (v_m0 + interval '1 month')::date group by rep_key, code;

  for r in
    select row_number() over (order by sheet_row) i, name, rep_key, parse_branches(branch_raw) br from reps where name <> '' and not is_admin order by sheet_row
  loop
    declare g numeric; rt numeric; dm numeric;
    begin
      select coalesce(sum(case when coalesce(qty, 0) < 0 then 0 else coalesce(total, 0) end), 0),
             coalesce(sum(case when coalesce(qty, 0) < 0 then abs(coalesce(total, 0)) else 0 end), 0),
             coalesce(sum(case when coalesce(qty, 0) < 0 and return_kind = 'تالف' then abs(coalesce(total, 0)) else 0 end), 0)
        into g, rt, dm from sales where rep_key = r.rep_key and r.rep_key <> '' and day >= v_m0 and day < (v_m0 + interval '1 month')::date;
      if cardinality(r.br) = 0 and g = 0 and rt = 0 then continue; end if;
      v_stale := 0; v_unres := 0; v_carried := 0;
      select min(d) into v_first from (
        select min(day) d from jard where rep_key = r.rep_key and r.rep_key <> ''
        union all select min(day) from tawrid where rep_key = r.rep_key and r.rep_key <> ''
        union all select min(day) from sales where rep_key = r.rep_key and r.rep_key <> '') z;
      v_new := v_first is null or (v_ref - v_first) < 30;
      foreach b in array (case when cardinality(r.br) = 0 then array[''] else r.br end) loop
        begin
          select v_carried + count(*) into v_carried from jsonb_array_elements(t_balances(r.name, b)) e where (e ->> 'balance')::numeric > 0;
        exception when others then null; end;
        exit when cardinality(r.br) <= 1;
      end loop;
      foreach b in array r.br loop
        begin lst := t_stale(b, 21, 500, r.name); exception when others then lst := '[]'; end;
        v_stale := v_stale + jsonb_array_length(lst);
        select coalesce(array_agg(sr.code), '{}') into v_rc from stale_reasons sr
          where sr.code <> '' and exists (select 1 from unnest(parse_branches(sr.branch)) x where nar(x) = nar(b));
        select v_unres + count(*) into v_unres from jsonb_array_elements(lst) e
          where (e ->> 'days')::int >= 30 and not (norm(e ->> 'code') = any(v_rc));
      end loop;
      insert into _ev values (r.i, r.name, rkey(r.name), r.br, r2(g), r2(rt - dm), r2(g - rt),
        (select t from (select target t, sheet_row from targets where month_key = p_mk and rep <> '' and target > 0 and rep_key = rkey(r.name)
                        order by sheet_row desc limit 1) z),
        v_stale, v_unres, null, r2(dm), v_carried, v_new);
    end;
  end loop;

  select coalesce(avg(net::float8), 0) into v_avg from _ev where net > 0;

  -- متوسط بيع الصنف
  update _ev set details = d.details from (
    select e.i, coalesce(jsonb_agg(x.det order by x.ord) filter (where x.det is not null), '[]') details
    from _ev e
    left join lateral (
      with codes as (
        select code, min(o) o from (
          select code, 1::bigint * 10000000000 + sheet_row o from jard where rep_key = e.rk and code <> ''
          union all select code, 2::bigint * 10000000000 + sheet_row from tawrid where rep_key = e.rk and code <> '' and coalesce(qty, 0) > 0
          union all select code, 3::bigint * 10000000000 + f from _iq where _iq.rk = e.rk and q > 0
        ) z group by code
      )
      select c.o ord, case when oth.n > 0 then jsonb_build_object(
          'code', c.code, 'name', coalesce(nullif((select name from items where items.code = c.code order by sheet_row desc limit 1), ''), c.code),
          'qty', greatest(0, coalesce(my.q, 0)), 'avg', r1(oth.s / oth.n),
          'pct', r0(greatest(0, coalesce(my.q, 0)) / (oth.s / oth.n) * 100)) end det
      from codes c
      left join _iq my on my.rk = e.rk and my.code = c.code
      left join lateral (select sum(iq.q) s, count(*) n from _ev e2 join _iq iq on iq.rk = e2.rk and iq.code = c.code and iq.q > 0 where e2.i <> e.i) oth on true
    ) x on true
    group by e.i
  ) d where d.i = _ev.i;

  with sc as (
    select e.*, jsonb_array_length(details) ic,
      (select count(*) from jsonb_array_elements(details) d where (d ->> 'pct')::numeric < 100) ib,
      case when jsonb_array_length(details) > 0 then
        (select sum(least((d ->> 'pct')::float8, 100)) from jsonb_array_elements(details) d) / jsonb_array_length(details) / 100 end iidx,
      case when v_avg > 0 then net::float8 / v_avg else 0 end vr
    from _ev e
  ), sc2 as (
    select sc.*, greatest(0, least(vr / 1.2, 1)) vf,
      case when target is not null then greatest(0, r1((net / target * 100)::numeric)) end tpct,
      15 + case when target is null then 30 else 0 end + case when iidx is null then 20 else 0 end vmax
    from sc
  ), sc3 as (
    select sc2.*,
      case when tpct is not null then 30 * least(tpct, 100) / 100.0 end ts,
      case when iidx is not null then 20 * iidx end isc,
      vmax * vf vs,
      -- الرواكد كنسبة من الأصناف اللي معاه: 0% = 20 كاملة، و30% أو أكتر = صفر. المندوب الجديد: مش محسوبة
      case when is_new then null
           else 20 * greatest(0, 1 - ((stale + unresolved)::float8 / greatest(carried, stale, 1)) / 0.30) end ss,
      case when gross > 0 then 15 * greatest(0, 1 - (ret::float8 / gross::float8) / 0.10) else 0 end rs
    from sc2
  ), fin as (
    select sc3.*, r0(((coalesce(ts, 0) + vs + coalesce(isc, 0) + coalesce(ss, 0) + rs) * case when ss is null then 100.0 / 80 else 1 end)::numeric) score from sc3
  ), ranked as (
    select fin.*, row_number() over (order by score desc, net desc, i) rnk from fin
  )
  select jsonb_build_object('avgNet', r2(v_avg::numeric), 'total', (select count(*) from _ev),
    'rows', coalesce(jsonb_agg(jsonb_build_object(
      'name', name, 'branches', to_jsonb(branches), 'gross', gross, 'ret', ret, 'net', net, 'target', target,
      'stale', stale, 'unresolved', unresolved, 'carried', carried, 'isNew', is_new, 'retDamaged', dmg, 'itemsCompared', ic, 'itemsBelow', ib, 'itemsIndex', iidx,
      'weakItems', (select coalesce(jsonb_agg(d order by (d ->> 'pct')::numeric, o), '[]') from (
          select d, o from jsonb_array_elements(details) with ordinality x(d, o) where (d ->> 'pct')::numeric < 100
          order by (d ->> 'pct')::numeric, o limit 5) w),
      'targetPct', tpct,
      'retRate', case when gross > 0 then r1((ret / gross * 100)::numeric) else 0 end,
      'volPct', r0((vr * 100)::numeric),
      'parts', jsonb_build_object(
        'target', case when ts is null then null else jsonb_build_object('score', r1(ts::numeric), 'max', 30) end,
        'volume', jsonb_build_object('score', r1(vs::numeric), 'max', vmax),
        'items', case when isc is null then null else jsonb_build_object('score', r1(isc::numeric), 'max', 20) end,
        'stale', case when ss is null then null else jsonb_build_object('score', r1(ss::numeric), 'max', 20) end,
        'returns', jsonb_build_object('score', r1(rs::numeric), 'max', 15)),
      'score', score, 'grade', t_grade(score), 'rank', rnk) order by rnk), '[]'))
  into res from ranked;
  return res;
end $function$;

CREATE OR REPLACE FUNCTION public.t_rep_evaluations_cached(p_mk text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare d jsonb;
begin
  select data into d from eval_cache where mk = p_mk and at > now() - interval '10 minutes';
  if d is not null then return d; end if;
  d := t_rep_evaluations(p_mk);
  insert into eval_cache (mk, at, data) values (p_mk, now(), d) on conflict (mk) do update set at = excluded.at, data = excluded.data;
  return d;
end $function$;

CREATE OR REPLACE FUNCTION public.t_rep_evaluations_v2(p_mk text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare
  cfg jsonb := ev2_cfg();
  v_m0 date := make_date(split_part(p_mk, '-', 1)::int, split_part(p_mk, '-', 2)::int, 1);
  v_mk1 text; v_mk2 text; d0 jsonb; d1 jsonb; d2 jsonb; res jsonb;
begin
  v_mk1 := to_char(v_m0 - interval '1 month', 'YYYY-MM');
  v_mk2 := to_char(v_m0 - interval '2 months', 'YYYY-MM');
  d0 := t_rep_eval_month_cached(p_mk);
  d1 := t_rep_eval_month_cached(v_mk1);
  d2 := t_rep_eval_month_cached(v_mk2);

  with hist as (
    select rkey(e ->> 'name') k, (cfg -> 'w3' ->> 0)::float8 w, (e ->> 'score')::float8 s, p_mk mk
      from jsonb_array_elements(d0 -> 'rows') e where not (e ->> 'incomplete')::boolean
    union all
    select rkey(e ->> 'name'), (cfg -> 'w3' ->> 1)::float8, (e ->> 'score')::float8, v_mk1
      from jsonb_array_elements(d1 -> 'rows') e where not (e ->> 'incomplete')::boolean
    union all
    select rkey(e ->> 'name'), (cfg -> 'w3' ->> 2)::float8, (e ->> 'score')::float8, v_mk2
      from jsonb_array_elements(d2 -> 'rows') e where not (e ->> 'incomplete')::boolean
  ), agg as (
    select k, sum(w * s) / sum(w) s3, jsonb_agg(jsonb_build_object('mk', mk, 'score', s) order by mk desc) months
    from hist group by k
  ), cur as (
    select e, o, rkey(e ->> 'name') k, (e ->> 'incomplete')::boolean inc
    from jsonb_array_elements(d0 -> 'rows') with ordinality x(e, o)
  ), ranked as (
    select cur.*, agg.s3, agg.months,
      case when not cur.inc then row_number() over (partition by cur.inc order by agg.s3 desc nulls last, (e ->> 'score')::float8 desc, o) end rnk
    from cur left join agg on agg.k = cur.k
  )
  select jsonb_build_object(
    'v2', true, 'mk', p_mk, 'season', d0 -> 'season', 'workDays', d0 -> 'workDays', 'weeks', d0 -> 'weeks',
    'minDays', d0 -> 'minDays', 'stMedian', d0 -> 'stMedian',
    'avgNet', (select r2(avg((xn.v ->> 'net')::numeric)) from jsonb_array_elements(d0 -> 'rows') xn(v) where (xn.v ->> 'net')::numeric > 0),
    'total', (select count(*) from cur where not inc),
    'rows', coalesce(jsonb_agg(e || jsonb_build_object(
        'score3', case when s3 is null then null else r0(s3::numeric) end,
        'history', coalesce(months, '[]'::jsonb),
        'rank', rnk,
        -- لو عنده تارجت متسجل وحقق أقل من 80% منه، أقصى تقييم ممكن ياخده "جيد جدًا" (مش "ممتاز") مهما كانت باقي الدرجات
        'grade', case
          when (e ->> 'targetPct') is not null and (e ->> 'targetPct')::numeric < 80
               and t_grade((e ->> 'score')::numeric) = 'ممتاز'
          then 'جيد جدًا'
          else t_grade((e ->> 'score')::numeric)
        end)
      order by rnk nulls last, (e ->> 'score')::float8 desc), '[]'))
  into res from ranked;
  return res;
end $function$;

CREATE OR REPLACE FUNCTION public.t_reps_targets(u jsonb, p_mk text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  v_today date := biz_today(); v_months jsonb; v_mk text := norm(coalesce(p_mk, ''));
  v_m0 date; v_m1 date; v_end date; v_elapsed int; v_total int; v_left int; v_cur boolean; res jsonb;
begin
  select jsonb_agg(to_char((date_trunc('month', v_today) - make_interval(months => g))::date, 'YYYY-MM') order by g)
    into v_months from generate_series(0, 11) g;
  if not v_months @> to_jsonb(v_mk) then v_mk := v_months ->> 0; end if;
  v_m0 := to_date(v_mk || '-01', 'YYYY-MM-DD');
  v_m1 := (v_m0 + interval '1 month')::date;
  v_end := least(v_m1 - 1, v_today);
  v_cur := v_today >= v_m0 and v_today < v_m1;
  v_elapsed := greatest(v_end - v_m0 + 1, 1);
  v_total := v_m1 - v_m0;
  v_left := case when v_cur then v_m1 - v_today else 0 end;   -- أيام فاضلة في الشهر (بالنهارده)

  with r as (
    select name, coalesce(nullif(rep_key, ''), rkey(name)) k, parse_branches(branch_raw) br, sheet_row
    from reps where name <> '' and not is_admin
  ), s as (
    select rep_key k,
      sum(case when coalesce(qty, 0) > 0 then coalesce(total, 0) else 0 end) g,
      sum(case when coalesce(qty, 0) < 0 and coalesce(return_kind, '') <> 'رجوع للشركة' then abs(coalesce(total, 0)) else 0 end) rt,
      count(distinct day) filter (where coalesce(qty, 0) > 0) d,
      sum(case when day = v_today then coalesce(total, 0) else 0 end) today
    from sales where day >= v_m0 and day < v_m1 and coalesce(rep_key, '') <> '' group by rep_key
  ), t as (
    select distinct on (rep_key) rep_key k, target from targets
    where month_key = v_mk and coalesce(target, 0) > 0 and coalesce(rep, '') <> '' order by rep_key, sheet_row desc
  ), x as (
    select r.name, r.br, r.sheet_row, r2(coalesce(s.g, 0)) gross, r2(coalesce(s.rt, 0)) ret,
      r2(coalesce(s.g, 0) - coalesce(s.rt, 0)) net, coalesce(s.d, 0) days, r2(coalesce(s.today, 0)) today, t.target
    from r left join s on s.k = r.k left join t on t.k = r.k
    where (cardinality(r.br) > 0 or s.k is not null or t.k is not null)
      and branches_allowed(array_to_string(r.br, '،'), u -> 'allowedBranches')
  ), y as (
    select x.*,
      case when target > 0 then r1(net / target * 100) end pct,
      case when target > 0 then r2(greatest(target - net, 0)) end remaining,
      case when target > 0 and v_cur and v_left > 0 then r0(greatest(target - net, 0) / v_left) end need_day,
      case when target > 0 and v_cur then r1(net / v_elapsed * v_total / target * 100) end forecast
    from x
  )
  select jsonb_build_object(
    'monthKey', v_mk, 'months', v_months, 'current', v_cur,
    'elapsed', v_elapsed, 'totalDays', v_total, 'daysLeft', v_left,
    'totals', (select jsonb_build_object(
        'net', r2(coalesce(sum(net), 0)), 'gross', r2(coalesce(sum(gross), 0)), 'ret', r2(coalesce(sum(ret), 0)),
        'today', r2(coalesce(sum(today), 0)),
        'target', r2(coalesce(sum(target), 0)),
        'netTargeted', r2(coalesce(sum(net) filter (where target > 0), 0)),
        'pct', case when sum(target) > 0 then r1(sum(net) filter (where target > 0) / sum(target) * 100) end,
        'forecast', case when sum(target) > 0 and v_cur then r1(sum(net) filter (where target > 0) / v_elapsed * v_total / sum(target) * 100) end,
        'reps', count(*), 'withTarget', count(*) filter (where target > 0),
        'achieved', count(*) filter (where pct >= 100)) from y),
    'rows', coalesce((select jsonb_agg(jsonb_build_object(
        'name', name, 'branches', to_jsonb(br), 'gross', gross, 'ret', ret, 'net', net, 'today', today, 'days', days,
        'target', target, 'pct', pct, 'remaining', remaining, 'needPerDay', need_day, 'forecast', forecast)
      order by (pct is null), pct desc nulls last, net desc, sheet_row) from y), '[]'::jsonb)
  ) into res;
  return res;
end $function$;

CREATE OR REPLACE FUNCTION public.t_req_get(p_key text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  select result from write_requests where key = p_key and at > now() - interval '1 day'
$function$;

CREATE OR REPLACE FUNCTION public.t_req_put(p_key text, p_res jsonb)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
begin
  if p_key is null or p_key = '' then return; end if;
  insert into write_requests (key, result) values (p_key, p_res) on conflict (key) do update set result = excluded.result, at = now();
  delete from write_requests where at < now() - interval '2 days';
end $function$;

CREATE OR REPLACE FUNCTION public.t_sale_stock(u jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare v_hide boolean; res jsonb;
begin
  v_hide := not coalesce((u ->> 'isAdmin')::boolean, false) and jsonb_array_length(t_block_items(u)) > 0;
  select coalesce(jsonb_agg(jsonb_build_object('code', e -> 'code', 'name', e -> 'name',
           'balance', case when v_hide then null else e -> 'balance' end) order by o), '[]')
    into res from jsonb_array_elements(t_balances(u ->> 'name', u ->> 'branch')) with ordinality x(e, o)
    where (e ->> 'balance')::numeric > 0;
  return jsonb_build_object('hidden', v_hide, 'branch', u -> 'branch', 'items', res);
end $function$;

CREATE OR REPLACE FUNCTION public.t_save_stock(u jsonb, p_kind text, p_items jsonb, p_req text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare
  v_jard boolean := p_kind = 'jard'; v_key text; v_prev jsonb; v_today date := biz_today(); v_rk text := rkey(u ->> 'name');
  it jsonb; v_name text; v_q numeric; v_code record; v_now timestamptz := now(); n int := 0; v_res jsonb;
begin
  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception '%', case when v_jard then 'مفيش أصناف مضافة للجرد' else 'مفيش أصناف مضافة للتوريد' end;
  end if;
  perform pg_advisory_xact_lock(hashtext('stk:' || v_rk));
  v_key := case when norm(p_req) <> '' then (case when v_jard then 'saveJard_' else 'saveTawrid_' end) || v_rk || '_' || norm(p_req) end;
  v_prev := t_req_get(v_key);
  if v_prev is not null then return v_prev; end if;
  for it in select e from jsonb_array_elements(p_items) e loop
    n := n + 1;
    v_name := norm(it ->> 'itemName');
    v_q := js_number(case when v_jard then it -> 'count' else it -> 'qty' end);
    if v_jard and (v_name = '' or v_q is null or v_q < 0) then raise exception 'من فضلك أكمل بيانات الجرد بشكل صحيح'; end if;
    if not v_jard and (v_name = '' or v_q is null or v_q <= 0) then raise exception 'من فضلك أكمل بيانات التوريد بشكل صحيح'; end if;
    select * into v_code from t_code_for(v_name);
    if v_jard then
      insert into jard (sheet_row, code_raw, code, item_name, count, day, rep, rep_key, branch_raw, branch, ts, src)
      values (1000000000 + n, v_code.code_raw, v_code.code, v_name, v_q, v_today, u ->> 'name', v_rk, coalesce(u ->> 'branch', ''),
              coalesce((parse_branches(u ->> 'branch'))[1], ''), v_now, 'sb');
    else
      insert into tawrid (sheet_row, code_raw, code, item_name, qty, rep, rep_key, day, branch_raw, branch, ts, src)
      values (1000000000 + n, v_code.code_raw, v_code.code, v_name, v_q, u ->> 'name', v_rk, v_today, coalesce(u ->> 'branch', ''),
              coalesce((parse_branches(u ->> 'branch'))[1], ''), v_now, 'sb');
    end if;
  end loop;
  v_res := jsonb_build_object('ok', true, 'count', n, 'date', dmy(v_today), 'repName', u ->> 'name');
  perform t_req_put(v_key, v_res);
  return v_res;
end $function$;

CREATE OR REPLACE FUNCTION public.t_short_id()
 RETURNS text
 LANGUAGE sql
AS $function$ select substr(gen_random_uuid()::text, 1, 8) $function$;

CREATE OR REPLACE FUNCTION public.t_similarity(a jsonb, b jsonb)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare it jsonb; used boolean[]; i int; best numeric; bi int; s numeric; score numeric := 0; nb int := jsonb_array_length(b);
begin
  if jsonb_array_length(a) = 0 or nb = 0 then return 0; end if;
  used := array_fill(false, array[nb]);
  for it in select e from jsonb_array_elements(a) e loop
    best := -1; bi := 0;
    for i in 1..nb loop
      if not used[i] and (b -> (i - 1) ->> 'name') = (it ->> 'name') then
        s := (case when (b -> (i - 1) -> 'qty')::numeric = (it -> 'qty')::numeric then 0.25 else 0 end)
           + (case when (b -> (i - 1) -> 'price')::numeric = (it -> 'price')::numeric then 0.25 else 0 end);
        if s > best then best := s; bi := i; end if;
      end if;
    end loop;
    if bi > 0 then score := score + 0.5 + best; used[bi] := true; end if;
  end loop;
  return score / greatest(jsonb_array_length(a), nb);
end $function$;

CREATE OR REPLACE FUNCTION public.t_stale(p_branch text, p_window integer, p_limit integer, p_rep text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
with p as (
  select norm(p_branch) b, rkey(p_branch) bk,
         case when norm(p_rep) = '' then null else rkey(p_rep) end rk, biz_today() today
), rfb as (select * from rep_first_branch_map()),
fbreps as (select coalesce(array_agg(rfb.rep_key), '{}') ks from rfb, p where rkey(rfb.fb) = p.bk),
names as (select distinct on (code) code, name from items where code <> '' and name <> '' order by code, sheet_row desc),
seasons as (select distinct on (code) code, coalesce(raw ->> 'الموسم', '') as season from items where code <> '' order by code, sheet_row desc),
s0 as (
  select sh.sheet_row, sh.code, sh.rep, sh.day, coalesce(sh.qty, 0) qty, sh.return_kind, sh.ts, sh.branch_raw,
         (sh.branch_key = p.bk or (sh.branch = '' and sh.rep_key = any(fbreps.ks))) fm
  from sales sh cross join p cross join fbreps
  where p.b <> '' and (p.rk is null or sh.rep_key = p.rk) and sh.code <> '' and sh.day is not null
    and (sh.branch_key = p.bk or (sh.branch = '' and sh.rep_key = any(fbreps.ks)) or sh.multi)
), s as (
  select s0.* from s0 cross join p
  where fm or exists (select 1 from unnest(parse_branches(branch_raw)) x where rkey(x) = p.bk)
), j0 as (
  select j.sheet_row, j.code, j.rep, j.day, j.count qty, j.ts
  from jard j cross join p cross join fbreps
  where p.b <> '' and j.code <> '' and (p.rk is null or j.rep_key = p.rk)
    and (j.branch_key = p.bk or (j.branch = '' and j.rep_key = any(fbreps.ks)))
), t0 as (
  select t.sheet_row, t.code, t.rep, t.day, coalesce(t.qty, 0) qty, t.ts
  from tawrid t cross join p cross join fbreps
  where p.b <> '' and t.code <> '' and (p.rk is null or t.rep_key = p.rk)
    and (t.branch_key = p.bk or (t.branch = '' and t.rep_key = any(fbreps.ks)))
),
jent as (select * from j0 where day is not null and qty is not null),
supp as (select * from t0 where day is not null),
sent as (select * from s where fm and not (qty < 0 and return_kind = 'تالف')),
moves as (
  select code, rep, rkey(rep) rk, day, 1::bigint * 10000000000 + sheet_row ord from s where fm and rep <> ''
  union all select code, rep, rkey(rep), day, 2::bigint * 10000000000 + sheet_row from jent where rep <> ''
  union all select code, rep, rkey(rep), day, 3::bigint * 10000000000 + sheet_row from supp where rep <> ''
),
carried as (
  select code, min(ord) ord from (
    select code, 1::bigint * 10000000000 + sheet_row ord from s where fm
    union all select code, 2::bigint * 10000000000 + sheet_row from j0
    union all select code, 3::bigint * 10000000000 + sheet_row from t0
  ) x group by code
),
ls as (select code, max(day) last_sale from s where qty > 0 group by code),
fs as (select code, min(day) first_seen from (
  select code, day from jent union all select code, day from supp union all select code, day from sent) f group by code),
bl as (select distinct on (code) code, qty bqty, day bday, ts bts from jent order by code, day desc, coalesce(ts, 'epoch'::timestamptz) desc, sheet_row desc),
lsup as (select code, max(day) last_supply from supp where qty > 0 group by code),
sa as (select e.code, sum(e.qty) q from supp e left join bl on bl.code = e.code
       where bl.bday is null or (case when e.ts is not null and bl.bts is not null and e.day = bl.bday then e.ts > bl.bts else e.day >= bl.bday end)
       group by e.code),
na as (select e.code, sum(e.qty) q from sent e left join bl on bl.code = e.code
       where bl.bday is null or (case when e.ts is not null and bl.bts is not null and e.day = bl.bday then e.ts > bl.bts else e.day >= bl.bday end)
       group by e.code),
lm as (select distinct on (code) code, rep, rk from moves order by code, day desc, ord desc),
since as (select m.code, min(m.day) since from moves m join lm on lm.code = m.code and lm.rk = m.rk group by m.code),
calc as (
  select c.code, c.ord,
    case when ls.last_sale is not null then (p.today - ls.last_sale) else coalesce(p.today - fs.first_seen, p_window) end days,
    ls.last_sale is null never_sold,
    greatest(0, r2(coalesce(bl.bqty, 0) + coalesce(sa.q, 0) - coalesce(na.q, 0))) stock,
    lsup.last_supply,
    case when lm.code is null then null else jsonb_build_object('rep', lm.rep, 'since', dmy(si.since), 'days', p.today - si.since) end holder,
    coalesce(nm.name, c.code) iname,
    coalesce(se.season, '') iseason
  from carried c cross join p
  left join ls on ls.code = c.code left join fs on fs.code = c.code left join bl on bl.code = c.code
  left join sa on sa.code = c.code left join na on na.code = c.code left join lsup on lsup.code = c.code
  left join lm on lm.code = c.code left join since si on si.code = c.code left join names nm on nm.code = c.code
  left join seasons se on se.code = c.code
),
out as (select * from calc where days >= p_window and stock > 0
        order by (case when never_sold then days + 100000 else days end) desc, ord limit coalesce(nullif(p_limit, 0), 20))
select coalesce(jsonb_agg(jsonb_build_object(
    'code', code, 'name', iname, 'days', days, 'neverSold', never_sold, 'holder', holder,
    'stock', stock, 'stockKnown', true, 'lastSupply', coalesce(dmy(last_supply), ''), 'season', iseason)
  order by (case when never_sold then days + 100000 else days end) desc, ord), '[]'::jsonb)
from out
$function$;

CREATE OR REPLACE FUNCTION public.t_stale_reasons_report(u jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare res jsonb;
begin
  if not is_owner(u) then raise exception 'غير مصرح لك بمشاهدة الصفحة دي'; end if;
  select coalesce(jsonb_agg(jsonb_build_object('code', code, 'name', item_name, 'branch', branch, 'rep', rep, 'reason', reason,
           'date', coalesce(dmy(psd(raw -> 'تاريخ الكتابة')), norm(jtxt(raw -> 'تاريخ الكتابة'))))
           order by branch collate ar_sort, item_name collate ar_sort, sheet_row), '[]')
    into res from stale_reasons where branches_allowed(branch, u -> 'allowedBranches');
  return jsonb_build_object('user', u, 'reasons', res);
end $function$;

CREATE OR REPLACE FUNCTION public.t_target_progress(u jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare v_t numeric; v_mk text := t_month_key(biz_today()); v_sum numeric;
begin
  v_t := t_target_row(u ->> 'name', v_mk);
  if v_t is null then return null; end if;
  select coalesce(sum(total), 0) into v_sum from sales
    where rep_key = rkey(u ->> 'name') and day >= date_trunc('month', biz_today())::date and day < (date_trunc('month', biz_today()) + interval '1 month')::date;
  return jsonb_build_object('achieved', r2(v_sum), 'target', v_t, 'pct', greatest(0, r1(v_sum / v_t * 100)));
exception when others then return null;
end $function$;

CREATE OR REPLACE FUNCTION public.t_target_row(p_name text, p_mk text)
 RETURNS numeric
 LANGUAGE sql
 STABLE
AS $function$
  -- أول صف للمندوب ده في الشهر ده (لو التارجت فيه مش صالح = مفيش تارجت)
  select case when target > 0 then target else null end from (
    select target from targets where nar(rep) = nar(p_name) and month_key = p_mk order by sheet_row limit 1) x
$function$;

CREATE OR REPLACE FUNCTION public.t_time12(ts timestamp with time zone)
 RETURNS text
 LANGUAGE sql
AS $function$
  select case when ts is null then null else
    trim(to_char(ts at time zone 'Africa/Cairo', 'HH12:MI')) || ' ' ||
    (case to_char(ts at time zone 'Africa/Cairo', 'AM') when 'AM' then 'ص' else 'م' end)
  end
$function$;

CREATE OR REPLACE FUNCTION public.t_user(p_auth jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare
  v_email text := lower(norm(jtxt(p_auth -> 'email')));
  v_pin text := norm(jtxt(p_auth -> 'pin'));
  v_want text := norm(jtxt(p_auth -> 'branch'));
  r reps%rowtype; v_until timestamptz; v_br text[]; v_cur text;
begin
  if v_email = '' or v_pin = '' then return jsonb_build_object('err', 'لازم تسجل الدخول الأول'); end if;
  select until into v_until from auth_fail where email = v_email and until > now();
  if v_until is not null then
    return jsonb_build_object('err', 'محاولات دخول غلط كتير — التطبيق قافل مؤقتًا، حاول تاني بعد ' ||
      greatest(1, ceil(extract(epoch from v_until - now()) / 60))::int || ' دقيقة');
  end if;
  select * into r from reps where email = v_email order by sheet_row limit 1;
  if not found then return jsonb_build_object('err', 'الحساب ده مش مسجل، كلم المسؤول عن التطبيق', 'fail', true); end if;
  if r.pin = '' or r.pin <> v_pin then
    return jsonb_build_object('err', 'انتهت الجلسة أو الكود اتغيّر — سجل الدخول تاني', 'fail', true);
  end if;
  v_br := parse_branches(r.branch_raw);
  select b into v_cur from unnest(v_br) with ordinality x(b, o) where nar(b) = nar(v_want) order by o limit 1;
  v_cur := coalesce(v_cur, v_br[1], '');
  return jsonb_build_object(
    'email', v_email, 'name', r.name, 'branch', v_cur, 'branches', to_jsonb(v_br), 'isAdmin', r.is_admin,
    'photoUrl', norm(jtxt(r.raw -> 'الصورة')),
    'allowedBranches', case when r.is_admin and v_email <> 'elzenoukisales@gmail.com' then allowed_branches(r.name) else null end);
end $function$;

CREATE OR REPLACE FUNCTION public.t_weekly_off(v text)
 RETURNS text[]
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare s text := norm(v); j jsonb; days text[] := array['الأحد','الإثنين','الثلاثاء','الأربعاء','الخميس','الجمعة','السبت'];
begin
  if s = '' then return '{}'; end if;
  j := safe_jsonb(s);
  if j is null then return case when s = any(days) then array[s] else '{}' end; end if;
  if jsonb_typeof(j) <> 'array' then return '{}'; end if;
  return coalesce(array(select e #>> '{}' from jsonb_array_elements(j) with ordinality x(e, o)
    where jsonb_typeof(e) = 'string' and (e #>> '{}') = any(days) order by o), '{}');
end $function$;

CREATE OR REPLACE FUNCTION public.t_ymd(d date)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$ select to_char(d, 'YYYY-MM-DD') $function$;

CREATE OR REPLACE FUNCTION public.user_branches(u jsonb)
 RETURNS text[]
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select coalesce(array(select jsonb_array_elements_text(u -> 'branches')), '{}')
$function$;

CREATE OR REPLACE FUNCTION public.warm_eval_cache_()
 RETURNS void
 LANGUAGE plpgsql
AS $function$
declare v_mk text := to_char(biz_today(), 'YYYY-MM');
begin
  perform t_rep_eval_month_cached(v_mk);
  perform t_rep_eval_month_cached(to_char(date_trunc('month', biz_today()) - interval '1 month', 'YYYY-MM'));
  perform t_rep_eval_month_cached(to_char(date_trunc('month', biz_today()) - interval '2 months', 'YYYY-MM'));
exception when others then null;
end
$function$;

