-- Add generated columns after functions exist
alter table public."jard" add column "branch_key" text generated always as (rkey(branch)) stored;
alter table public."sales" add column "branch_key" text generated always as (rkey(branch)) stored;
alter table public."sales" add column "multi" boolean generated always as ((branch_raw ~ '[،,؛;|/]'::text)) stored;
alter table public."tawrid" add column "branch_key" text generated always as (rkey(branch)) stored;

-- Indexes
CREATE INDEX api_usage_at_idx ON public.api_usage USING btree (at);
CREATE INDEX api_usage_email_at_idx ON public.api_usage USING btree (email, at);
CREATE INDEX attendance_rep_day_idx ON public.attendance USING btree (rep_key, day);
CREATE UNIQUE INDEX attendance_rep_key_day_key ON public.attendance USING btree (rep_key, day);
CREATE UNIQUE INDEX item_targets_uniq ON public.item_targets USING btree (rep_key, code, month_key);
CREATE INDEX jard_branch_key_idx ON public.jard USING btree (branch_key);
CREATE INDEX jard_outbox_idx ON public.jard USING btree (id) WHERE ((src = 'sb'::text) AND (synced_at IS NULL));
CREATE INDEX jard_rep_day_idx ON public.jard USING btree (rep_key, day);
CREATE INDEX prices_email_idx ON public.prices USING btree (email);
CREATE INDEX sales_branch_key_idx ON public.sales USING btree (branch_key);
CREATE INDEX sales_code_idx ON public.sales USING btree (code);
CREATE INDEX sales_day_idx ON public.sales USING btree (day);
CREATE INDEX sales_multi_idx ON public.sales USING btree (branch_key) WHERE multi;
CREATE INDEX sales_outbox_idx ON public.sales USING btree (id) WHERE ((src = 'sb'::text) AND (synced_at IS NULL));
CREATE INDEX sales_rep_day_idx ON public.sales USING btree (rep_key, day);
CREATE INDEX sales_session_idx ON public.sales USING btree (session_id);
CREATE INDEX sessions_outbox_idx ON public.sessions USING btree (id) WHERE ((src = 'sb'::text) AND (synced_at IS NULL));
CREATE INDEX sessions_rep_day_idx ON public.sessions USING btree (rep_key, day);
CREATE INDEX sessions_rep_idx ON public.sessions USING btree (rep_key);
CREATE INDEX sessions_sid_idx ON public.sessions USING btree (session_id);
CREATE INDEX tawrid_branch_key_idx ON public.tawrid USING btree (branch_key);
CREATE INDEX tawrid_outbox_idx ON public.tawrid USING btree (id) WHERE ((src = 'sb'::text) AND (synced_at IS NULL));
CREATE INDEX tawrid_rep_day_idx ON public.tawrid USING btree (rep_key, day);



-- Scheduled job
select cron.schedule('warm_eval_cache', '*/8 * * * *', $$select public.warm_eval_cache_();$$);

